package com.spoontracker;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.*;

public class DropMechanicTest
{
    private static final DropContext EMPTY = new DropContext("test", 1, Collections.emptyMap());

    @Test
    public void calculatesFixedMultiRollCompositeAndGuaranteeExpectations()
    {
        assertEquals(400, DropMechanic.fixedDenominator(400).evaluate(EMPTY)
            .getExpectedCompletions().getAsDouble(), 0);

        double multi = DropMechanic.independentRolls(1.0 / 1024, 2).evaluate(EMPTY)
            .getExpectedCompletions().getAsDouble();
        assertEquals(512.2501, multi, .001);

        double composite = DropMechanic.composite(1.0 / 381, 1.0 / 16256,
            1.0 / 16256, 1.0 / 16256).evaluate(EMPTY).getExpectedCompletions().getAsDouble();
        assertTrue(composite > 355 && composite < 357);

        double guaranteed = DropMechanic.guaranteed(1.0 / 50, 50).evaluate(EMPTY)
            .getExpectedCompletions().getAsDouble();
        assertEquals(31.79, guaranteed, .02);
    }

    @Test
    public void exactVariableRatesGradeAndMissingOrDeterministicRatesDoNot()
    {
        Map<String, Double> metadata = new HashMap<>();
        metadata.put("item.1.probability", .002);
        assertEquals(500, DropMechanic.variable("item.1.probability")
            .evaluate(new DropContext("raid", 1, metadata)).getExpectedCompletions().getAsDouble(), 0);
        assertFalse(DropMechanic.variable("item.1.probability").evaluate(EMPTY).isGradable());
        assertFalse(DropMechanic.deterministic("fixed reward").evaluate(EMPTY).isGradable());
    }

    @Test
    public void historicalPreviewTierBoundariesAreStable()
    {
        assertEquals(SpoonTier.DIAMOND, HistoricalLuckResult.previewTier(.99));
        assertEquals(SpoonTier.GOLD, HistoricalLuckResult.previewTier(.90));
        assertEquals(SpoonTier.SILVER, HistoricalLuckResult.previewTier(.50));
        assertEquals(SpoonTier.WOODEN, HistoricalLuckResult.previewTier(.10));
        assertEquals(SpoonTier.BENT, HistoricalLuckResult.previewTier(.01));
        assertEquals(SpoonTier.SPORK, HistoricalLuckResult.previewTier(.0099));
    }
}

package com.spoontracker;

import java.util.Collections;
import java.util.List;
import net.runelite.client.game.ItemStack;
import org.junit.Test;

import static org.junit.Assert.*;

public class KillCountCorrelatorTest
{
    @Test
    public void correlatesKcAfterLoot()
    {
        BossCatalog catalog = new BossCatalog();
        KillCountCorrelator correlator = new KillCountCorrelator(catalog);
        correlator.addDrop(catalog.findByKey("zulrah").get(),
            Collections.singletonList(new ItemStack(12921, 1)),
            new DropContext("Zulrah", 100, Collections.emptyMap()));
        assertTrue(correlator.parseKillCount("Your Zulrah kill count is: 1,234.", 101).isPresent());
        List<KillCountCorrelator.PendingDrop> ready = correlator.drainReady(101);
        assertEquals(1, ready.size());
        assertEquals(Integer.valueOf(1234), ready.get(0).getKillCount());
    }

    @Test
    public void correlatesKcBeforeLootAndExpiresUnknown()
    {
        BossCatalog catalog = new BossCatalog();
        KillCountCorrelator correlator = new KillCountCorrelator(catalog);
        correlator.parseKillCount("Your kill count for Vorkath is: 99.", 10);
        KillCountCorrelator.PendingDrop known = correlator.addDrop(catalog.findByKey("vorkath").get(),
            Collections.singletonList(new ItemStack(22109, 1)),
            new DropContext("Vorkath", 11, Collections.emptyMap()));
        assertEquals(Integer.valueOf(99), known.getKillCount());
        assertEquals(1, correlator.drainReady(11).size());

        correlator.addDrop(catalog.findByKey("zulrah").get(),
            Collections.singletonList(new ItemStack(12921, 1)),
            new DropContext("Zulrah", 20, Collections.emptyMap()));
        assertTrue(correlator.drainReady(30).isEmpty());
        assertEquals(1, correlator.drainReady(31).size());
    }

    @Test
    public void recognizesCurrentGameMessageVariantsAndDelayedKc()
    {
        BossCatalog catalog = new BossCatalog();
        KillCountCorrelator correlator = new KillCountCorrelator(catalog);
        correlator.addDrop(catalog.findByKey("gauntlet").get(),
            Collections.singletonList(new ItemStack(25859, 1)),
            new DropContext("Corrupted Gauntlet", 100, Collections.emptyMap()));

        assertTrue(correlator.parseKillCount(
            "Your completion count for <col=ff0000>Corrupted Gauntlet</col> is: <col=ff0000>321</col>.",
            108).isPresent());
        List<KillCountCorrelator.PendingDrop> ready = correlator.drainReady(108);
        assertEquals(1, ready.size());
        assertEquals(Integer.valueOf(321), ready.get(0).getKillCount());
    }

    @Test
    public void usesPreloadedHiscoreOrCollectionLogCountAsFallback()
    {
        BossCatalog catalog = new BossCatalog();
        KillCountCorrelator correlator = new KillCountCorrelator(catalog);
        assertTrue(correlator.preloadKnownCount("Zulrah kills", 456));

        KillCountCorrelator.PendingDrop drop = correlator.addDrop(
            catalog.findByKey("zulrah").get(),
            Collections.singletonList(new ItemStack(12921, 1)),
            new DropContext("Zulrah", 100, Collections.emptyMap()));
        assertEquals(Integer.valueOf(456), drop.getKillCount());
    }
}

package com.spoontracker;

import java.time.Instant;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.*;

public class CollectionLogMatcherTest
{
    @Test
    public void matchesCanonicalVariantsAndSharedBossDrops()
    {
        CollectionLogMatcher matcher = new CollectionLogMatcher(new BossCatalog());
        TrackedUnique kbdPick = record("king_black_dragon", "King Black Dragon", 11920,
            SpoonTier.GOLD);
        TrackedUnique kqPick = record("kalphite_queen", "Kalphite Queen", 11920,
            SpoonTier.DIAMOND);
        TrackedUnique unrelated = record("zulrah", "Zulrah", 12922, SpoonTier.SILVER);

        List<TrackedUnique> matches = matcher.findRecords(11920,
            Arrays.asList(kbdPick, unrelated, kqPick));
        assertEquals(2, matches.size());
        assertEquals("Kalphite Queen", matches.get(0).getBossName());
        assertEquals("King Black Dragon", matches.get(1).getBossName());
        assertEquals(SpoonTier.DIAMOND, matcher.bestTier(matches));
    }

    @Test
    public void matchesChargedCollectionLogVariantToCanonicalRecord()
    {
        CollectionLogMatcher matcher = new CollectionLogMatcher(new BossCatalog());
        TrackedUnique sanguinesti = record("theatre_of_blood", "Theatre of Blood", 22323,
            SpoonTier.SILVER);
        assertEquals(1, matcher.findRecords(22481, Arrays.asList(sanguinesti)).size());
    }

    private static TrackedUnique record(String bossKey, String bossName, int itemId, SpoonTier tier)
    {
        return new TrackedUnique(bossKey, bossName, itemId, itemId, "Item", 10, 100.0,
            tier, Instant.EPOCH, BossCatalog.VERSION);
    }
}

