package com.spoontracker;

import com.peanubnutter.collectionlogluck.luck.probability.ProbabilityMath;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ProbabilityMathTest
{
    @Test
    public void matchesKnownBinomialValues()
    {
        assertEquals(0.1171875, ProbabilityMath.binomialProbability(10, 0.5, 3), 1e-12);
        assertEquals(0.376953125,
            ProbabilityMath.binomialCumulativeProbability(10, 0.5, 4), 1e-12);
        assertEquals(0.0, ProbabilityMath.binomialCumulativeProbability(10, 0.5, -1), 0);
        assertEquals(1.0, ProbabilityMath.binomialCumulativeProbability(10, 0.5, 10), 0);
    }

    @Test
    public void matchesKnownNormalValues()
    {
        assertEquals(0.5, ProbabilityMath.normalCumulativeProbability(0, 0, 1), 1e-7);
        assertEquals(0.975,
            ProbabilityMath.normalCumulativeProbability(1.959963984540054, 0, 1), 2e-7);
        assertEquals(0.3989422804014327, ProbabilityMath.standardNormalDensity(0), 1e-15);
    }
}

