package com.spoontracker;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import org.junit.Test;

import static org.junit.Assert.*;

public class CelebrationManagerTest
{
    @Test
    public void queuesCelebrationsWithoutDroppingAny()
    {
        MutableClock clock = new MutableClock();
        CelebrationManager manager = new CelebrationManager(clock);
        TrackedUnique one = record(1);
        TrackedUnique two = record(2);
        manager.enqueue(one);
        manager.enqueue(two);
        assertSame(one, manager.getActive(4));
        assertEquals(1, manager.queuedCount());
        clock.advance(Duration.ofSeconds(5));
        assertSame(two, manager.getActive(4));
        assertEquals(0, manager.queuedCount());
    }

    private static TrackedUnique record(int id)
    {
        return new TrackedUnique("boss", "Boss", id, id, "Item", 1, 100.0,
            SpoonTier.DIAMOND, Instant.EPOCH, BossCatalog.VERSION);
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.EPOCH;
        public ZoneId getZone() { return ZoneId.of("UTC"); }
        public Clock withZone(ZoneId zone) { return this; }
        public Instant instant() { return now; }
        void advance(Duration duration) { now = now.plus(duration); }
    }
}

package com.spoontracker;

import org.junit.Test;

import static org.junit.Assert.*;
import java.util.Arrays;

public class SpoonTierTest
{
    @Test
    public void gradesEveryBoundary()
    {
        assertEquals(SpoonTier.DIAMOND, SpoonTier.from(10, 100).orElse(null));
        assertEquals(SpoonTier.GOLD, SpoonTier.from(11, 100).orElse(null));
        assertEquals(SpoonTier.GOLD, SpoonTier.from(50, 100).orElse(null));
        assertEquals(SpoonTier.SILVER, SpoonTier.from(51, 100).orElse(null));
        assertEquals(SpoonTier.SILVER, SpoonTier.from(100, 100).orElse(null));
        assertEquals(SpoonTier.WOODEN, SpoonTier.from(101, 100).orElse(null));
        assertEquals(SpoonTier.WOODEN, SpoonTier.from(200, 100).orElse(null));
        assertEquals(SpoonTier.BENT, SpoonTier.from(201, 100).orElse(null));
        assertEquals(SpoonTier.BENT, SpoonTier.from(500, 100).orElse(null));
        assertEquals(SpoonTier.SPORK, SpoonTier.from(501, 100).orElse(null));
    }

    @Test
    public void refusesUnknownOrInvalidRates()
    {
        assertFalse(SpoonTier.from(0, 100).isPresent());
        assertFalse(SpoonTier.from(1, 0).isPresent());
        assertFalse(SpoonTier.from(1, Double.NaN).isPresent());
    }

    @Test
    public void everyTierHasItsOwnBundledIcon()
    {
        for (SpoonTier tier : SpoonTier.values())
        {
            assertNotNull(tier.getDisplayName(), SpoonTrackerPlugin.class.getResource(tier.getIconResource()));
        }
    }

    @Test
    public void everyTierHasItsOwnSound()
    {
        assertEquals(SpoonTier.values().length, Arrays.stream(SpoonTier.values())
            .mapToInt(SpoonTier::getSoundEffectId).distinct().count());
    }
}

package com.spoontracker;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SpoonSoundTest
{
    @Test
    public void audiblePresetsUseDistinctSoundEffects()
    {
        long audible = Arrays.stream(SpoonSound.values()).filter(SpoonSound::isAudible).count();
        long distinct = Arrays.stream(SpoonSound.values())
            .filter(SpoonSound::isAudible)
            .mapToInt(SpoonSound::getSoundEffectId)
            .distinct()
            .count();

        assertEquals(audible, distinct);
    }

    @Test
    public void silentPresetDoesNotPlay()
    {
        assertFalse(SpoonSound.SILENT.isAudible());
        assertTrue(SpoonSound.TWINKLE.isAudible());
    }

    @Test
    public void defaultsPreserveExistingTierSounds()
    {
        SpoonTrackerConfig config = new SpoonTrackerConfig() { };

        assertEquals(SpoonTier.DIAMOND.getSoundEffectId(), config.diamondSound().getSoundEffectId());
        assertEquals(SpoonTier.GOLD.getSoundEffectId(), config.goldSound().getSoundEffectId());
        assertEquals(SpoonTier.SILVER.getSoundEffectId(), config.silverSound().getSoundEffectId());
        assertEquals(SpoonTier.WOODEN.getSoundEffectId(), config.woodenSound().getSoundEffectId());
        assertEquals(SpoonTier.BENT.getSoundEffectId(), config.bentSound().getSoundEffectId());
        assertEquals(SpoonTier.SPORK.getSoundEffectId(), config.sporkSound().getSoundEffectId());
    }
}

package com.spoontracker;

import com.google.gson.Gson;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.*;

public class FullCollectionLogCatalogTest
{
    @Test
    public void bundledCatalogMatchesPinnedReferenceBaseline()
    {
        FullCollectionLogCatalog catalog = new FullCollectionLogCatalog(new Gson());
        catalog.validate();
        assertEquals(1692, catalog.size());
        assertEquals("Tanzanite fang", catalog.findItem(12922).get().getName());
        assertEquals("Bludgeon axon", catalog.findItem(13276).get().getName());
        assertEquals("BinomialDrop", catalog.findItem(12922).get().getMechanic());
        assertFalse(catalog.activitiesForItem(12922).isEmpty());
    }

    @Test
    public void catalogContainsEverySupportStatus()
    {
        FullCollectionLogCatalog catalog = new FullCollectionLogCatalog(new Gson());
        assertTrue(catalog.getItems().stream().anyMatch(item -> "SUPPORTED".equals(item.getStatus())));
        assertTrue(catalog.getItems().stream().anyMatch(item -> "DETERMINISTIC".equals(item.getStatus())));
        assertTrue(catalog.getItems().stream().anyMatch(item -> "MISSING_COUNTER".equals(item.getStatus())));
        assertTrue(catalog.getItems().stream().anyMatch(item -> "UNSUPPORTED".equals(item.getStatus())));
    }

    @Test
    public void cluePageNamesAreHumanReadable()
    {
        FullCollectionLogCatalog catalog = new FullCollectionLogCatalog(new Gson());
        assertFalse(catalog.getItems().stream()
            .flatMap(item -> item.getActivities().stream())
            .anyMatch(activity -> activity.getPage().contains("TextInfo")
                || activity.getPage().contains("ToTitleCase")));
        assertTrue(catalog.getItems().stream()
            .flatMap(item -> item.getActivities().stream())
            .anyMatch(activity -> "Medium Treasure Trails".equals(activity.getPage())));
    }

    @Test
    public void gameCachePagesOverrideFallbacksAndAddNewItemsAsUngraded()
    {
        FullCollectionLogCatalog catalog = new FullCollectionLogCatalog(new Gson());
        catalog.registerGamePage(ActivityCategory.BOSSES, "Zulrah",
            Collections.singletonMap(12922, "Tanzanite fang"));
        catalog.registerGamePage(ActivityCategory.OTHER, "New Activity",
            Collections.singletonMap(999999, "New collection item"));

        assertEquals("Zulrah", catalog.activitiesForItem(12922).get(0).getPageName());
        assertEquals("UNSUPPORTED", catalog.findItem(999999).get().getStatus());
        assertEquals("New Activity", catalog.activitiesForItem(999999).get(0).getPageName());
        assertEquals(1693, catalog.size());
    }
}

package com.spoontracker;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.game.ItemStack;
import org.junit.Test;

import static org.junit.Assert.*;

public class TrackingEngineTest
{
    private final BossCatalog catalog = new BossCatalog();
    private final TrackingEngine engine = new TrackingEngine(new RateCalculator(),
        Clock.fixed(Instant.parse("2026-07-22T12:00:00Z"), ZoneOffset.UTC));

    @Test
    public void recognizesMultipleUniquesAndSuppressesDuplicates()
    {
        BossDefinition zulrah = catalog.findByKey("zulrah").get();
        List<ItemStack> loot = Arrays.asList(new ItemStack(12921, 1),
            new ItemStack(12921, 1), new ItemStack(12922, 1), new ItemStack(995, 1000));
        DropContext context = new DropContext("Zulrah", 10, Collections.emptyMap());
        List<TrackedUnique> first = engine.recognize(zulrah, loot, 50, context, Collections.emptyList());
        assertEquals(2, first.size());
        assertEquals(SpoonTier.DIAMOND, first.get(0).getTier());

        List<TrackedUnique> second = engine.recognize(zulrah, loot, 51, context, first);
        assertTrue(second.isEmpty());
    }

    @Test
    public void sameItemCanCountForDifferentBosses()
    {
        BossDefinition kbd = catalog.findByKey("king_black_dragon").get();
        BossDefinition vorkath = catalog.findByKey("vorkath").get();
        List<TrackedUnique> records = new ArrayList<>(engine.recognize(kbd,
            Collections.singletonList(new ItemStack(11286, 1)), 10,
            new DropContext("King Black Dragon", 1, Collections.emptyMap()), Collections.emptyList()));
        records.addAll(engine.recognize(vorkath, Collections.singletonList(new ItemStack(11286, 1)),
            20, new DropContext("Vorkath", 2, Collections.emptyMap()), records));
        assertEquals(2, records.size());
        assertNotEquals(records.get(0).getBossKey(), records.get(1).getBossKey());
    }

    @Test
    public void missingRaidProbabilityProducesUngradedRecord()
    {
        BossDefinition raid = catalog.findByKey("chambers_of_xeric").get();
        List<TrackedUnique> records = engine.recognize(raid,
            Collections.singletonList(new ItemStack(20997, 1)), 15,
            new DropContext("Chambers of Xeric", 1, Collections.emptyMap()), Collections.emptyList());
        assertEquals(1, records.size());
        assertNull(records.get(0).getTier());
        assertNull(records.get(0).getEffectiveDenominator());
    }
}

