package com.spoontracker;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.OptionalDouble;
import org.junit.Test;

import static org.junit.Assert.*;

public class RateCalculatorTest
{
    @Test
    public void fixedAndRunSpecificRatesAreSeparated()
    {
        BossCatalog catalog = new BossCatalog();
        RateCalculator calculator = new RateCalculator();
        BossDefinition zulrah = catalog.findByKey("zulrah").get();
        UniqueDefinition fang = zulrah.findUnique(12922).get();
        double exactZulrahExpectation = 1.0 / (1.0 - Math.pow(1023.0 / 1024.0, 2));
        assertEquals(exactZulrahExpectation, calculator.expectedKillCount(zulrah, fang,
            new DropContext("Zulrah", 1, Collections.emptyMap())).getAsDouble(), 0.0001);

        BossDefinition cox = catalog.findByKey("chambers_of_xeric").get();
        UniqueDefinition bow = cox.findUnique(20997).get();
        assertFalse(calculator.expectedKillCount(cox, bow,
            new DropContext("Chambers of Xeric", 1, Collections.emptyMap())).isPresent());
        Map<String, Double> metadata = new HashMap<>();
        metadata.put("item.20997.probability", .0005);
        OptionalDouble expected = calculator.expectedKillCount(cox, bow,
            new DropContext("Chambers of Xeric", 1, metadata));
        assertEquals(2000, expected.getAsDouble(), 0.001);

        BossDefinition gauntlet = catalog.findByKey("gauntlet").get();
        UniqueDefinition enhanced = gauntlet.findUnique(25859).get();
        assertEquals(2000, calculator.expectedKillCount(gauntlet, enhanced,
            new DropContext("The Gauntlet", 2, Collections.emptyMap())).getAsDouble(), 0);
        assertEquals(400, calculator.expectedKillCount(gauntlet, enhanced,
            new DropContext("The Corrupted Gauntlet", 3, Collections.emptyMap())).getAsDouble(), 0);
    }
}

package com.spoontracker;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

public final class UniqueDefinition
{
    private final int canonicalItemId;
    private final String name;
    private final double fixedDenominator;
    private final DropMechanic dropMechanic;
    private final Set<Integer> itemIds;

    public UniqueDefinition(int canonicalItemId, String name, double fixedDenominator, int... variants)
    {
        this(canonicalItemId, name, fixedDenominator,
            fixedDenominator > 0
                ? DropMechanic.fixedDenominator(fixedDenominator)
                : DropMechanic.variable("item." + canonicalItemId + ".probability"),
            variants);
    }

    public UniqueDefinition(int canonicalItemId, String name, DropMechanic dropMechanic, int... variants)
    {
        this(canonicalItemId, name, 0, dropMechanic, variants);
    }

    private UniqueDefinition(int canonicalItemId, String name, double fixedDenominator,
        DropMechanic dropMechanic, int... variants)
    {
        this.canonicalItemId = canonicalItemId;
        this.name = name;
        this.fixedDenominator = fixedDenominator;
        this.dropMechanic = dropMechanic;
        Set<Integer> ids = new LinkedHashSet<>();
        ids.add(canonicalItemId);
        for (int variant : variants)
        {
            ids.add(variant);
        }
        this.itemIds = Collections.unmodifiableSet(ids);
    }

    public int getCanonicalItemId()
    {
        return canonicalItemId;
    }

    public String getName()
    {
        return name;
    }

    public double getFixedDenominator()
    {
        return fixedDenominator;
    }

    public DropMechanic getDropMechanic()
    {
        return dropMechanic;
    }

    public Set<Integer> getItemIds()
    {
        return itemIds;
    }

    public boolean matches(int itemId)
    {
        return itemIds.contains(itemId);
    }
}

