package com.spoontracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.AlphaComposite;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

final class CollectionLogSpoonOverlay extends WidgetItemOverlay
{
    private static final Color UNGRADED_COLOR = new Color(190, 150, 255);

    private final Client client;
    private final SpoonTrackerConfig config;
    private final CollectionLogMatcher matcher;
    private final Supplier<List<TrackedUnique>> recordsSupplier;
    private final TooltipManager tooltipManager;
    private final SpoonIconSet spoonIcons;
    private final Supplier<List<HistoricalLuckResult>> historicalSupplier;

    CollectionLogSpoonOverlay(Client client, SpoonTrackerConfig config, BossCatalog catalog,
        Supplier<List<TrackedUnique>> recordsSupplier, TooltipManager tooltipManager)
    {
        this(client, config, catalog, recordsSupplier, java.util.Collections::emptyList, tooltipManager);
    }

    CollectionLogSpoonOverlay(Client client, SpoonTrackerConfig config, BossCatalog catalog,
        Supplier<List<TrackedUnique>> recordsSupplier,
        Supplier<List<HistoricalLuckResult>> historicalSupplier, TooltipManager tooltipManager)
    {
        this.client = client;
        this.config = config;
        this.matcher = new CollectionLogMatcher(catalog);
        this.recordsSupplier = recordsSupplier;
        this.tooltipManager = tooltipManager;
        this.historicalSupplier = historicalSupplier;
        this.spoonIcons = new SpoonIconSet(12);
        showOnInterfaces(InterfaceID.COLLECTION);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (!config.collectionLogSpoons())
        {
            return;
        }
        List<TrackedUnique> matches = matcher.findRecords(itemId, recordsSupplier.get());
        if (matches.isEmpty())
        {
            renderHistoricalPreview(graphics, itemId, widgetItem);
            return;
        }

        Rectangle bounds = widgetItem.getCanvasBounds();
        SpoonTier best = matcher.bestTier(matches);
        Color color = best == null ? UNGRADED_COLOR : best.getColor();
        int badgeX = bounds.x + bounds.width - 14;
        int badgeY = bounds.y + bounds.height - 14;

        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(15, 15, 18, 205));
        g.fillRoundRect(badgeX, badgeY, 14, 14, 4, 4);
        g.setColor(color);
        g.setStroke(new BasicStroke(1f));
        g.drawRoundRect(badgeX, badgeY, 13, 13, 4, 4);
        g.drawImage(spoonIcons.get(best), badgeX + 1, badgeY + 1, null);

        if (matches.size() > 1)
        {
            String count = Integer.toString(matches.size());
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
            int textWidth = g.getFontMetrics().stringWidth(count);
            int countX = badgeX - textWidth;
            int countY = badgeY + 8;
            g.setColor(Color.BLACK);
            g.fillOval(countX - 2, countY - 9, textWidth + 4, 11);
            g.setColor(Color.WHITE);
            g.drawString(count, countX, countY);
        }
        g.dispose();

        net.runelite.api.Point mouse = client.getMouseCanvasPosition();
        if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
        {
            tooltipManager.add(new Tooltip(buildTooltip(matches)));
        }
    }

    private void renderHistoricalPreview(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (!config.historicalLuck())
        {
            return;
        }
        HistoricalLuckResult preview = null;
        for (HistoricalLuckResult candidate : historicalSupplier.get())
        {
            if (candidate.getItemId() == itemId && candidate.getPreviewTier() != null)
            {
                preview = candidate;
                break;
            }
        }
        if (preview == null)
        {
            return;
        }
        Rectangle bounds = widgetItem.getCanvasBounds();
        int badgeX = bounds.x + bounds.width - 14;
        int badgeY = bounds.y + bounds.height - 14;
        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, .68f));
        g.setColor(new Color(15, 15, 18, 185));
        g.fillRoundRect(badgeX, badgeY, 14, 14, 4, 4);
        g.setColor(preview.getPreviewTier().getColor());
        g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER,
            10f, new float[]{2f, 2f}, 0f));
        g.drawRoundRect(badgeX, badgeY, 13, 13, 4, 4);
        g.drawImage(spoonIcons.get(preview.getPreviewTier()), badgeX + 1, badgeY + 1, null);
        g.dispose();

        net.runelite.api.Point mouse = client.getMouseCanvasPosition();
        if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
        {
            tooltipManager.add(new Tooltip(ColorUtil.wrapWithColorTag("Spoon Tracker Preview",
                new Color(255, 194, 51)) + "</br>" + preview.getItemName() + ": "
                + String.format("%.1f%% overall luck", preview.getOverallLuck() * 100)
                + "</br>Historical preview — not an earned spoon"));
        }
    }

    private static String buildTooltip(List<TrackedUnique> records)
    {
        StringBuilder tooltip = new StringBuilder(ColorUtil.wrapWithColorTag(
            "Spoon Tracker", new Color(255, 194, 51)));
        for (TrackedUnique record : records)
        {
            Color color = record.getTier() == null ? UNGRADED_COLOR : record.getTier().getColor();
            String tier = record.getTier() == null ? "Mystery Spoon" : record.getTier().getDisplayName();
            String kc = record.getObtainedKillCount() == null
                ? "Count unknown" : "Count " + record.getObtainedKillCount();
            tooltip.append("</br>")
                .append(record.getBossName())
                .append(": ")
                .append(ColorUtil.wrapWithColorTag(tier, color))
                .append(" (").append(kc).append(')');
        }
        return tooltip.toString();
    }
}

package com.spoontracker;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

final class CollectionLogMatcher
{
    private final BossCatalog catalog;

    CollectionLogMatcher(BossCatalog catalog)
    {
        this.catalog = catalog;
    }

    List<TrackedUnique> findRecords(int displayedItemId, Collection<TrackedUnique> records)
    {
        Set<Integer> canonicalIds = new HashSet<>();
        canonicalIds.add(displayedItemId);
        for (BossDefinition boss : catalog.getBosses())
        {
            boss.findUnique(displayedItemId)
                .map(UniqueDefinition::getCanonicalItemId)
                .ifPresent(canonicalIds::add);
        }

        List<TrackedUnique> matches = new ArrayList<>();
        for (TrackedUnique record : records)
        {
            if (canonicalIds.contains(record.getCanonicalItemId()))
            {
                matches.add(record);
            }
        }
        matches.sort(Comparator.comparing(TrackedUnique::getBossName));
        return matches;
    }

    SpoonTier bestTier(Collection<TrackedUnique> records)
    {
        SpoonTier best = null;
        for (TrackedUnique record : records)
        {
            if (record.getTier() != null && (best == null || record.getTier().ordinal() < best.ordinal()))
            {
                best = record.getTier();
            }
        }
        return best;
    }
}

package com.spoontracker;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public final class HistoricalLogSnapshot
{
    private final String username;
    private final Instant fetchedAt;
    private final String source;
    private final Map<Integer, Integer> quantities;
    private final Map<String, Integer> counters;

    public HistoricalLogSnapshot(String username, Instant fetchedAt, String source,
        Map<Integer, Integer> quantities, Map<String, Integer> counters)
    {
        this.username = username;
        this.fetchedAt = fetchedAt;
        this.source = source;
        this.quantities = Collections.unmodifiableMap(new LinkedHashMap<>(quantities));
        this.counters = Collections.unmodifiableMap(new LinkedHashMap<>(counters));
    }

    public String getUsername() { return username; }
    public Instant getFetchedAt() { return fetchedAt; }
    public String getSource() { return source; }
    public Map<Integer, Integer> getQuantities() { return quantities; }
    public Map<String, Integer> getCounters() { return counters; }

    public HistoricalLogSnapshot merge(HistoricalLogSnapshot newer)
    {
        Map<Integer, Integer> mergedItems = new LinkedHashMap<>(quantities);
        newer.quantities.forEach((id, quantity) -> mergedItems.merge(id, quantity, Math::max));
        Map<String, Integer> mergedCounters = new LinkedHashMap<>(counters);
        newer.counters.forEach((name, count) -> mergedCounters.merge(name, count, Math::max));
        String mergedSource;
        if (source.equals(newer.source)) mergedSource = source;
        else mergedSource = "In-game Collection Log pages";
        return new HistoricalLogSnapshot(newer.username, newer.fetchedAt,
            mergedSource, mergedItems, mergedCounters);
    }
}

