package com.spoontracker;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.game.ItemStack;

public final class KillCountCorrelator
{
    private static final Pattern[] KC_PATTERNS = {
        // Keep this in step with RuneLite's Chat Commands KC parser. OSRS uses several
        // shapes here ("completed", "subdued", "completion count for", harvest count,
        // success count, etc.), not just "<boss> kill count".
        Pattern.compile("Your (?:(?:completion count for|subdued|completed)\\s+)?(.+?)\\s+"
            + "(?:(?:(?:kill|harvest|lap|completion|success|total ticket)\\s+)?(?:count\\s+)?)?"
            + "is:\\s*([\\d,]+)\\.?", Pattern.CASE_INSENSITIVE),
        Pattern.compile("Your kill count for (.+?) is: ([\\d,]+)\\.?", Pattern.CASE_INSENSITIVE)
    };
    // LootReceived, ServerNpcLoot, and the game message are independent event paths.
    // A three-tick timeout was short enough for valid KC messages to miss the drop.
    private static final int WINDOW_TICKS = 10;
    private static final int SECONDARY_SOURCE_WINDOW_TICKS = 50;

    private final BossCatalog catalog;
    private final Deque<PendingDrop> pending = new ArrayDeque<>();
    private final Map<String, SeenKillCount> recentKillCounts = new HashMap<>();
    private final Map<String, Integer> knownKillCounts = new HashMap<>();

    public KillCountCorrelator(BossCatalog catalog)
    {
        this.catalog = catalog;
    }

    public PendingDrop addDrop(BossDefinition boss, Collection<ItemStack> items,
        DropContext context)
    {
        int windowTicks = BossDefinition.normalize(context.getSource())
            .equals(BossDefinition.normalize(boss.getName()))
            ? WINDOW_TICKS : SECONDARY_SOURCE_WINDOW_TICKS;
        String sourceKey = BossDefinition.normalize(context.getSource());
        SeenKillCount recent = recentKillCounts.get(sourceKey);
        if (recent == null)
        {
            recent = recentKillCounts.get(bossKey(boss));
        }
        Integer kc = recent != null && Math.abs(context.getTick() - recent.tick) <= windowTicks
            ? recent.killCount : null;
        if (kc == null)
        {
            kc = knownKillCounts.get(sourceKey);
        }
        if (kc == null)
        {
            kc = knownKillCounts.get(bossKey(boss));
        }
        PendingDrop drop = new PendingDrop(boss, new ArrayList<>(items), context, kc, windowTicks);
        pending.add(drop);
        return drop;
    }

    public Optional<BossKillCount> parseKillCount(String message, int tick)
    {
        String clean = message == null ? "" : message.replaceAll("<[^>]+>", "");
        for (Pattern pattern : KC_PATTERNS)
        {
            Matcher matcher = pattern.matcher(clean);
            if (!matcher.find())
            {
                continue;
            }
            Optional<BossDefinition> boss = catalog.findBySource(matcher.group(1));
            if (!boss.isPresent())
            {
                continue;
            }
            int count;
            try
            {
                count = Integer.parseInt(matcher.group(2).replace(",", ""));
            }
            catch (NumberFormatException ex)
            {
                continue;
            }
            String sourceKey = BossDefinition.normalize(matcher.group(1));
            recentKillCounts.put(sourceKey, new SeenKillCount(count, tick));
            recentKillCounts.put(bossKey(boss.get()), new SeenKillCount(count, tick));
            knownKillCounts.put(sourceKey, count);
            knownKillCounts.put(bossKey(boss.get()), count);
            for (PendingDrop drop : pending)
            {
                if (drop.boss.getKey().equals(boss.get().getKey())
                    && Math.abs(drop.context.getTick() - tick) <= drop.windowTicks)
                {
                    drop.killCount = count;
                }
            }
            return Optional.of(new BossKillCount(boss.get(), count));
        }
        return Optional.empty();
    }

    /**
     * Adds a session baseline obtained from hiscores or an in-game Collection Log counter.
     * A later same-kill chat message still takes priority over this value.
     */
    public boolean preloadKnownCount(String source, int count)
    {
        if (source == null || count < 0)
        {
            return false;
        }
        Optional<BossDefinition> boss = findBossForCounter(source);
        if (!boss.isPresent())
        {
            return false;
        }
        String normalized = normalizeCounterSource(source);
        knownKillCounts.merge(normalized, count, Math::max);
        if (boss.get().getAliases().size() == 1)
        {
            knownKillCounts.merge(bossKey(boss.get()), count, Math::max);
        }
        return true;
    }

    private Optional<BossDefinition> findBossForCounter(String source)
    {
        Optional<BossDefinition> direct = catalog.findBySource(source);
        return direct.isPresent() ? direct : catalog.findBySource(normalizeCounterSource(source));
    }

    private static String normalizeCounterSource(String source)
    {
        return BossDefinition.normalize(source)
            .replaceFirst("\\s+(?:kills?|completions?|chests?|harvests?|successes?)$", "")
            .trim();
    }

    private static String bossKey(BossDefinition boss)
    {
        return "boss:" + boss.getKey();
    }

    public List<PendingDrop> drainReady(int currentTick)
    {
        List<PendingDrop> ready = new ArrayList<>();
        while (!pending.isEmpty())
        {
            PendingDrop first = pending.peek();
            if (first.killCount == null && currentTick - first.context.getTick() <= first.windowTicks)
            {
                break;
            }
            ready.add(pending.remove());
        }
        recentKillCounts.values().removeIf(kc -> currentTick - kc.tick > SECONDARY_SOURCE_WINDOW_TICKS);
        return ready;
    }

    public void clear()
    {
        pending.clear();
        recentKillCounts.clear();
        knownKillCounts.clear();
    }

    public static final class PendingDrop
    {
        private final BossDefinition boss;
        private final List<ItemStack> items;
        private final DropContext context;
        private Integer killCount;
        private final int windowTicks;

        PendingDrop(BossDefinition boss, List<ItemStack> items, DropContext context, Integer killCount,
            int windowTicks)
        {
            this.boss = boss;
            this.items = items;
            this.context = context;
            this.killCount = killCount;
            this.windowTicks = windowTicks;
        }

        public BossDefinition getBoss() { return boss; }
        public List<ItemStack> getItems() { return items; }
        public DropContext getContext() { return context; }
        public Integer getKillCount() { return killCount; }
    }

    public static final class BossKillCount
    {
        private final BossDefinition boss;
        private final int killCount;

        BossKillCount(BossDefinition boss, int killCount)
        {
            this.boss = boss;
            this.killCount = killCount;
        }

        public BossDefinition getBoss() { return boss; }
        public int getKillCount() { return killCount; }
    }

    private static final class SeenKillCount
    {
        private final int killCount;
        private final int tick;

        private SeenKillCount(int killCount, int tick)
        {
            this.killCount = killCount;
            this.tick = tick;
        }
    }
}

