    SILENT("Silent", -1);

    private final String displayName;
    private final int soundEffectId;

    SpoonSound(String displayName, int soundEffectId)
    {
        this.displayName = displayName;
        this.soundEffectId = soundEffectId;
    }

    public int getSoundEffectId()
    {
        return soundEffectId;
    }

    public boolean isAudible()
    {
        return soundEffectId >= 0;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.spoontracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import net.runelite.client.ui.FontManager;

final class SpoonShareCardRenderer
{
    static final int WIDTH = 960;
    static final int HEIGHT = 540;
    private static final Color BRONZE = new Color(181, 151, 91);
    private static final Color GOLD_TEXT = new Color(255, 194, 51);
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("d MMM uuuu")
        .withZone(ZoneId.systemDefault());

    private final SpoonIconSet spoonIcons = new SpoonIconSet(180);

    BufferedImage render(TrackedUnique record, BufferedImage itemImage)
    {
        BufferedImage card = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = card.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        Color tierColor = record.getTier() == null ? new Color(190, 150, 255) : record.getTier().getColor();

        g.setColor(new Color(25, 20, 15));
        g.fillRect(0, 0, WIDTH, HEIGHT);
        for (int y = 18; y < HEIGHT; y += 34)
        {
            g.setColor(new Color(48, 38, 27));
            g.drawLine(0, y, WIDTH, y);
            g.setColor(new Color(18, 14, 11));
            g.drawLine(0, y + 1, WIDTH, y + 1);
        }
        g.setColor(new Color(42, 34, 25, 245));
        g.fillRoundRect(22, 22, WIDTH - 44, HEIGHT - 44, 18, 18);
        g.setStroke(new BasicStroke(5f));
        g.setColor(new Color(91, 70, 42));
        g.drawRoundRect(24, 24, WIDTH - 49, HEIGHT - 49, 18, 18);
        g.setStroke(new BasicStroke(2f));
        g.setColor(BRONZE);
        g.drawRoundRect(31, 31, WIDTH - 63, HEIGHT - 63, 13, 13);
        g.setColor(tierColor);
        g.fillRoundRect(37, 37, WIDTH - 74, 8, 6, 6);

        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(27f));
        drawText(g, "SPOON TRACKER", 64, 88, GOLD_TEXT);
        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(46f));
        drawFitted(g, tierName(record), 64, 610, 146, tierColor);
        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(36f));
        drawFitted(g, record.getItemName(), 64, 610, 201, new Color(255, 152, 31));
        g.setFont(FontManager.getRunescapeFont().deriveFont(26f));
        drawFitted(g, "from " + record.getBossName(), 64, 610, 242, new Color(222, 210, 188));

        g.drawImage(spoonIcons.get(record.getTier()), 704, 65, null);
        if (itemImage != null)
        {
            Object oldInterpolation = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            g.drawImage(itemImage, 722, 258, 144, 144, null);
            if (oldInterpolation != null)
            {
                g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
            }
        }

        drawStat(g, 64, 292, 166, "KILL COUNT", record.getObtainedKillCount() == null
            ? "Unknown" : Integer.toString(record.getObtainedKillCount()), tierColor);
        drawStat(g, 245, 292, 166, "DROP RATE", record.getEffectiveDenominator() == null
            ? "Unknown" : String.format("1/%.0f", record.getEffectiveDenominator()), tierColor);
        drawStat(g, 426, 292, 184, "LUCK RATIO", ratio(record), tierColor);

        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(24f));
        drawFitted(g, flavor(record.getTier()), 64, 610, 435, tierColor);
        g.setFont(FontManager.getRunescapeSmallFont().deriveFont(20f));
        String date = record.getObtainedAt() == null ? "Tracked since install"
            : "Tracked since install  |  " + DATE_FORMAT.format(record.getObtainedAt());
        drawText(g, date, 64, 478, new Color(176, 161, 137));
        drawText(g, "First observed item + activity pair", 64, 504, new Color(132, 119, 99));

        g.dispose();
        return card;
    }

    private static String tierName(TrackedUnique record)
    {
        return record.getTier() == null ? "Mystery Spoon" : record.getTier().getDisplayName();
    }

    private static String ratio(TrackedUnique record)
    {
        if (record.getObtainedKillCount() == null || record.getEffectiveDenominator() == null
            || record.getEffectiveDenominator() <= 0)
        {
            return "Unknown";
        }
        return String.format("%.2fx", record.getObtainedKillCount() / record.getEffectiveDenominator());
    }

    private static String flavor(SpoonTier tier)
    {
        if (tier == null) return "The cutlery drawer remains mysterious.";
        switch (tier)
        {
            case DIAMOND: return "Disgustingly spooned.";
            case GOLD: return "Streamer client detected.";
            case SILVER: return "Perfectly respectable cutlery.";
            case WOODEN: return "The drop-rate tax has been paid.";
            case BENT: return "Surely the next kill.";
            default: return "Not even the right utensil.";
        }
    }

    private static void drawStat(Graphics2D g, int x, int y, int width, String label, String value, Color accent)
    {
        g.setColor(new Color(24, 19, 14));
        g.fillRoundRect(x, y, width, 94, 10, 10);
        g.setColor(new Color(101, 80, 50));
        g.drawRoundRect(x, y, width, 94, 10, 10);
        g.setFont(FontManager.getRunescapeSmallFont().deriveFont(18f));
        drawCentered(g, label, x, width, y + 29, new Color(176, 161, 137));
        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(28f));
        drawCentered(g, value, x, width, y + 70, accent);
    }

    private static void drawCentered(Graphics2D g, String text, int x, int width, int baseline, Color color)
    {
        drawText(g, text, x + Math.max(0, (width - g.getFontMetrics().stringWidth(text)) / 2), baseline, color);
    }

    private static void drawFitted(Graphics2D g, String text, int left, int right, int baseline, Color color)
    {
        while (g.getFontMetrics().stringWidth(text) > right - left && text.length() > 4)
        {
            text = text.substring(0, text.length() - 2);
        }
        if (g.getFontMetrics().stringWidth(text) > right - left || !text.equals(text.trim()))
        {
            text = text.trim();
        }
        drawText(g, text, left, baseline, color);
    }

    private static void drawText(Graphics2D g, String text, int x, int baseline, Color color)
    {
        g.setColor(Color.BLACK);
        g.drawString(text, x + 2, baseline + 2);
        g.setColor(color);
        g.drawString(text, x, baseline);
    }
}

package com.spoontracker;

public final class FirstAcquisitionCalculator
{
    public RateEvaluation evaluate(ActivityDefinition activity, UniqueDefinition unique, DropContext context)
    {
        if ("gauntlet".equals(activity.getKey()))
        {
            boolean corrupted = BossDefinition.normalize(context.getSource()).contains("corrupted");
            switch (unique.getCanonicalItemId())
            {
                case 4207:
                case 23956:
                    return RateEvaluation.exact(corrupted ? 50 : 120, "Encounter-specific rate");
                case 25859:
                    return RateEvaluation.exact(corrupted ? 400 : 2000, "Encounter-specific rate");
                case 23757:
                    return RateEvaluation.exact(corrupted ? 800 : 2000, "Encounter-specific rate");
                default:
                    return RateEvaluation.unavailable("Encounter-specific rate", "Unknown Gauntlet reward");
            }
        }
        return unique.getDropMechanic().evaluate(context);
    }
}

