package com.spoontracker;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ItemComposition;
import net.runelite.api.StructComposition;
import net.runelite.client.game.ItemManager;

public final class FullCollectionLogCatalog
{
    public static final int EXPECTED_BASELINE_ITEMS = 1692;
    public static final String PINNED_COMMIT = "a2c8086d572c5015eedba6b71bbbb4a30790b213";
    private static final int[] COLLECTION_LOG_TAB_STRUCT_IDS = {471, 472, 473, 474, 475};
    private static final int TAB_NAME_PARAM = 682;
    private static final int TAB_ENUM_PARAM = 683;
    private static final int PAGE_NAME_PARAM = 689;
    private static final int PAGE_ITEMS_ENUM_PARAM = 690;

    private final Manifest manifest;
    private final Map<Integer, CatalogItem> byItemId = new HashMap<>();
    private final Map<String, List<CatalogItem>> byActivity = new LinkedHashMap<>();
    private final Map<Integer, java.util.Set<String>> observedPages = new HashMap<>();
    private final Map<Integer, Map<String, ActivityCategory>> observedPageCategories = new HashMap<>();
    private final Map<Integer, Integer> aliases = new HashMap<>();

    public FullCollectionLogCatalog(Gson gson)
    {
        InputStream stream = FullCollectionLogCatalog.class.getResourceAsStream("collection-log-catalog.json");
        if (stream == null)
        {
            throw new IllegalStateException("Bundled full Collection Log catalog is missing");
        }
        try (InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
        {
            manifest = gson.fromJson(reader, Manifest.class);
        }
        catch (Exception ex)
        {
            throw new IllegalStateException("Unable to load bundled full Collection Log catalog", ex);
        }
        validate();
        for (CatalogItem item : manifest.items)
        {
            byItemId.put(item.id, item);
            for (CatalogActivity activity : item.activities)
            {
                byActivity.computeIfAbsent(activity.key, ignored -> new ArrayList<>()).add(item);
            }
        }
    }

    public void validate()
    {
        if (manifest == null || manifest.schemaVersion != 1 || manifest.items == null
            || manifest.itemCount != manifest.items.size()
            || manifest.itemCount < EXPECTED_BASELINE_ITEMS)
        {
            throw new IllegalStateException("Full Collection Log catalog parity check failed");
        }
        if (!PINNED_COMMIT.equals(manifest.upstreamCommit))
        {
            throw new IllegalStateException("Unexpected Collection Log Luck source commit");
        }
        Map<Integer, String> ids = new HashMap<>();
        for (CatalogItem item : manifest.items)
        {
            if (item.id <= 0 || item.name == null || item.name.trim().isEmpty()
                || item.mechanic == null || item.status == null
                || item.activities == null || item.activities.isEmpty())
            {
                throw new IllegalStateException("Invalid full-log entry: " + item.field);
            }
            for (CatalogActivity activity : item.activities)
            {
                if (activity.key == null || activity.key.trim().isEmpty()
                    || activity.page == null || activity.page.trim().isEmpty()
                    || activity.page.contains("TextInfo") || activity.page.contains("ToTitleCase"))
                {
                    throw new IllegalStateException("Malformed Collection Log activity for " + item.name);
                }
            }
            if (com.peanubnutter.collectionlogluck.luck.LogItemInfo.findByItemId(item.id) == null)
            {
                throw new IllegalStateException("Unknown item id in full-log catalog: " + item.id);
            }
            String previous = ids.put(item.id, item.name);
            if (previous != null && !previous.equalsIgnoreCase(item.name))
            {
                throw new IllegalStateException("Item id belongs to two full-log entries: " + item.id);
            }
        }
    }

    public Optional<CatalogItem> findItem(int itemId)
    {
        return Optional.ofNullable(byItemId.get(canonicalItemId(itemId)));
    }

    public List<CatalogItem> getItems()
    {
        return Collections.unmodifiableList(manifest.items);
    }

    public Map<String, List<CatalogItem>> getItemsByActivity()
    {
        return Collections.unmodifiableMap(byActivity);
    }

    public List<ActivityDefinition> activitiesForItem(int itemId)
    {
        int canonicalId = canonicalItemId(itemId);
        CatalogItem item = byItemId.get(canonicalId);
        if (item == null)
        {
            return Collections.emptyList();
        }
        List<ActivityDefinition> result = new ArrayList<>();
        java.util.Set<String> capturedPages = observedPages.get(canonicalId);
        if (capturedPages != null && !capturedPages.isEmpty())
        {
            for (String page : capturedPages)
            {
                ActivityCategory category = observedPageCategories
                    .getOrDefault(canonicalId, Collections.emptyMap())
                    .getOrDefault(page, item.activities.get(0).getCategory());
                String key = BossDefinition.normalize(page).replaceAll("[^a-z0-9]+", "_")
                    .replaceAll("(^_|_$)", "");
                DropMechanic mechanic = ReferenceMechanicAdapter.forItem(canonicalId, key);
                result.add(new ActivityDefinition(key, page, category, page,
                    Collections.singletonList(page), Collections.singletonList(
                        new UniqueDefinition(canonicalId, item.name, mechanic))));
            }
            return result;
        }
        for (CatalogActivity activity : item.activities)
        {
            DropMechanic mechanic = ReferenceMechanicAdapter.forItem(canonicalId, activity.key);
            UniqueDefinition unique = new UniqueDefinition(canonicalId, item.name, mechanic);
            result.add(new ActivityDefinition(activity.key, activity.page, activity.getCategory(),
                activity.page, Collections.singletonList(activity.page), Collections.singletonList(unique)));
        }
        return result;
    }

    public void observePage(String pageName, java.util.Set<Integer> itemIds)
    {
        if (pageName == null || pageName.trim().isEmpty() || itemIds == null) return;
        for (Integer itemId : itemIds)
        {
            int canonicalId = canonicalItemId(itemId);
            if (byItemId.containsKey(canonicalId))
            {
                observedPages.computeIfAbsent(canonicalId, ignored -> new java.util.LinkedHashSet<>())
                    .add(pageName);
            }
        }
    }

    public List<ActivityDefinition> resolve(String source, int itemId)
    {
        int canonicalId = canonicalItemId(itemId);
        List<ActivityDefinition> candidates = activitiesForItem(canonicalId);
        if (source == null || source.trim().isEmpty()) return candidates;
        String normalized = BossDefinition.normalize(source);
        List<ActivityDefinition> exact = new ArrayList<>();
        for (ActivityDefinition candidate : candidates)
        {
            if (candidate.matchesSource(source)
                || normalized.contains(BossDefinition.normalize(candidate.getName()))
                || BossDefinition.normalize(candidate.getName()).contains(normalized))
            {
                exact.add(candidate);
            }
        }
        List<ActivityDefinition> selected = exact.isEmpty() ? candidates : exact;
        List<ActivityDefinition> sourceSpecific = new ArrayList<>();
        for (ActivityDefinition candidate : selected)
        {
            CatalogItem item = byItemId.get(canonicalId);
            UniqueDefinition unique = new UniqueDefinition(canonicalId, item.name,
                ReferenceMechanicAdapter.forItemSource(canonicalId, source));
            sourceSpecific.add(new ActivityDefinition(candidate.getKey(), candidate.getName(),
                candidate.getCategory(), candidate.getPageName(),
                Collections.singletonList(source), Collections.singletonList(unique)));
        }
        return sourceSpecific;
    }

    /**
     * Loads the authoritative, current Collection Log page/item layout from the game cache.
     * This performs no network access and also exposes newly released slots as ungraded until
     * their probability mechanics are added to the pinned catalog.
     */
    public int loadGameCollectionLog(Client client, ItemManager itemManager)
    {
        Set<Integer> discovered = new java.util.LinkedHashSet<>();
        for (int tabStructId : COLLECTION_LOG_TAB_STRUCT_IDS)
        {
            StructComposition tab = client.getStructComposition(tabStructId);
            if (tab == null) continue;
            ActivityCategory category = ActivityCategory.fromDisplayName(
                tab.getStringValue(TAB_NAME_PARAM));
            EnumComposition pages = client.getEnum(tab.getIntValue(TAB_ENUM_PARAM));
            if (pages == null || pages.getIntVals() == null) continue;
            for (int pageStructId : pages.getIntVals())
            {
                StructComposition page = client.getStructComposition(pageStructId);
                if (page == null) continue;
                String pageName = page.getStringValue(PAGE_NAME_PARAM);
                EnumComposition pageItems = client.getEnum(page.getIntValue(PAGE_ITEMS_ENUM_PARAM));
                if (pageName == null || pageName.trim().isEmpty()
                    || pageItems == null || pageItems.getIntVals() == null)
                {
                    continue;
                }
                Map<Integer, String> items = new LinkedHashMap<>();
                for (int rawItemId : pageItems.getIntVals())
                {
                    int itemId = canonicalCollectionLogItemId(rawItemId);
                    aliases.put(rawItemId, itemId);
                    ItemComposition composition = itemManager.getItemComposition(itemId);
                    String name = composition == null ? "Item " + itemId : composition.getName();
                    items.put(itemId, name);
                    discovered.add(itemId);
                }
                registerGamePage(category, pageName, items);
            }
        }
        return discovered.size();
    }

    void registerGamePage(ActivityCategory category, String pageName, Map<Integer, String> items)
    {
        if (category == null || pageName == null || pageName.trim().isEmpty() || items == null)
        {
            return;
        }
        for (Map.Entry<Integer, String> entry : items.entrySet())
        {
            int itemId = entry.getKey();
            CatalogItem item = byItemId.get(itemId);
            if (item == null)
            {
                item = CatalogItem.runtimeUnsupported(itemId, entry.getValue(), category, pageName);
                manifest.items.add(item);
                byItemId.put(itemId, item);
            }
            observedPages.computeIfAbsent(itemId, ignored -> new java.util.LinkedHashSet<>())
                .add(pageName);
            observedPageCategories.computeIfAbsent(itemId, ignored -> new LinkedHashMap<>())
                .put(pageName, category);
        }
    }

    private int canonicalItemId(int itemId)
    {
        Integer alias = aliases.get(itemId);
        if (alias != null)
        {
            return alias;
        }
        int mapped = canonicalCollectionLogItemId(itemId);
        return byItemId.containsKey(mapped) ? mapped : itemId;
    }

    private static int canonicalCollectionLogItemId(int itemId)
    {
        switch (itemId)
        {
            case 10859: return 25617;
            case 10877: return 25618;
            case 10878: return 25619;
            case 10879: return 25620;
            case 10880: return 25621;
            case 10881: return 25622;
            case 10882: return 25623;
            case 13273: return 25624;
            case 12019: return 25627;
            case 12020: return 25628;
            case 24882: return 25629;
            case 12854: return 25630;
            default: return itemId;
        }
    }

    public int size() { return manifest.items.size(); }
    public String getVersion() { return manifest.catalogVersion; }
    public String getSnapshotDate() { return manifest.snapshotDate; }

    static final class Manifest
    {
        int schemaVersion;
        String catalogVersion;
        String snapshotDate;
        String upstreamRepository;
        String upstreamCommit;
        int itemCount;
        List<CatalogItem> items;
    }

    public static final class CatalogItem
    {
        private int id;
        private String name;
        private String field;
        private String mechanic;
        private String status;
        private List<String> sourceCounters;
        private List<CatalogActivity> activities;

        public int getId() { return id; }
        public String getName() { return name; }
        public String getField() { return field; }
        public String getMechanic() { return mechanic; }
        public String getStatus() { return status; }
        public List<String> getSourceCounters() { return Collections.unmodifiableList(sourceCounters); }
        public List<CatalogActivity> getActivities() { return Collections.unmodifiableList(activities); }

        private static CatalogItem runtimeUnsupported(int id, String name,
            ActivityCategory category, String page)
        {
            CatalogItem item = new CatalogItem();
            item.id = id;
            item.name = name == null || name.trim().isEmpty() ? "Item " + id : name;
            item.field = "RUNTIME_" + id;
            item.mechanic = "UnimplementedDrop";
            item.status = "UNSUPPORTED";
            item.sourceCounters = Collections.emptyList();
            item.activities = Collections.singletonList(
                CatalogActivity.of(category, page));
            return item;
        }
    }

    public static final class CatalogActivity
    {
        private String key;
        private String category;
        private String page;

        public String getKey() { return key; }
        public ActivityCategory getCategory() { return ActivityCategory.fromDisplayName(category); }
        public String getPage() { return page; }

        private static CatalogActivity of(ActivityCategory category, String page)
        {
            CatalogActivity activity = new CatalogActivity();
            activity.key = BossDefinition.normalize(page).replaceAll("[^a-z0-9]+", "_")
                .replaceAll("(^_|_$)", "");
            activity.category = category.getDisplayName();
            activity.page = page;
            return activity;
        }
    }
}

package com.spoontracker;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;

public final class CelebrationManager
{
    private final Clock clock;
    private final Deque<TrackedUnique> queue = new ArrayDeque<>();
    private TrackedUnique active;
    private Instant startedAt;

    public CelebrationManager(Clock clock)
    {
        this.clock = clock;
    }

    public void enqueue(TrackedUnique record)
    {
        queue.add(record);
    }

    public TrackedUnique getActive(int durationSeconds)
    {
        Instant now = clock.instant();
        if (active != null && Duration.between(startedAt, now).toMillis() >= durationSeconds * 1000L)
        {
            active = null;
        }
        if (active == null && !queue.isEmpty())
        {
            active = queue.remove();
            startedAt = now;
        }
        return active;
    }

    public double progress(int durationSeconds)
    {
        if (active == null || startedAt == null)
        {
            return 1;
        }
        return Math.min(1, Duration.between(startedAt, clock.instant()).toMillis()
            / (durationSeconds * 1000.0));
    }

    public int queuedCount()
    {
        return queue.size();
    }

    public void clear()
    {
        queue.clear();
        active = null;
        startedAt = null;
    }
}

package com.spoontracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;

public class ActivityDefinition
{
    private final String key;
    private final String name;
    private final ActivityCategory category;
    private final String pageName;
    private final Set<String> aliases;
    private final List<UniqueDefinition> uniques;

    public ActivityDefinition(String key, String name, ActivityCategory category, String pageName,
        List<String> aliases, List<UniqueDefinition> uniques)
    {
        this.key = key;
        this.name = name;
        this.category = category;
        this.pageName = pageName;
        Set<String> normalized = new LinkedHashSet<>();
        normalized.add(BossDefinition.normalize(name));
        normalized.add(BossDefinition.normalize(pageName));
        for (String alias : aliases)
        {
            normalized.add(BossDefinition.normalize(alias));
        }
        this.aliases = Collections.unmodifiableSet(normalized);
        this.uniques = Collections.unmodifiableList(new ArrayList<>(uniques));
    }

    public String getKey() { return key; }
    public String getName() { return name; }
    public ActivityCategory getCategory() { return category; }
    public String getPageName() { return pageName; }
    public Set<String> getAliases() { return aliases; }
    public List<UniqueDefinition> getUniques() { return uniques; }

    public boolean matchesSource(String source)
    {
        return source != null && aliases.contains(BossDefinition.normalize(source));
    }

    public Optional<UniqueDefinition> findUnique(int itemId)
    {
        return uniques.stream().filter(unique -> unique.matches(itemId)).findFirst();
    }
}

