import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.ImageUtil;

public final class SpoonCelebrationOverlay extends Overlay
{
    private final Client client;
    private final ItemManager itemManager;
    private final SpoonTrackerConfig config;
    private final CelebrationManager celebrations;
    private final SpoonIconSet spoonIcons;
    private int cachedItemId = -1;
    private BufferedImage cachedItemImage;

    @Inject
    public SpoonCelebrationOverlay(Client client, ItemManager itemManager, SpoonTrackerConfig config,
        CelebrationManager celebrations)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        this.celebrations = celebrations;
        spoonIcons = new SpoonIconSet(30);
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.celebrationOverlay())
        {
            return null;
        }
        TrackedUnique record = celebrations.getActive(config.celebrationSeconds());
        if (record == null)
        {
            return null;
        }

        double progress = celebrations.progress(config.celebrationSeconds());
        float alpha = (float) Math.max(0, Math.min(1, Math.min(progress / .08, (1 - progress) / .18)));
        double intro = Math.min(1, progress / .10);
        int width = 286;
        int height = 76;
        int x = (client.getCanvasWidth() - width) / 2;
        int y = 28 - (int) ((1 - intro) * 10);
        Color tierColor = record.getTier() == null ? new Color(190, 150, 255) : record.getTier().getColor();

        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setComposite(AlphaComposite.SrcOver.derive(Math.max(0, alpha)));
        // Compact RuneScape-style interface card: dark timber, bronze trim, and small corner rivets.
        g.setColor(new Color(0, 0, 0, 125));
        g.fillRoundRect(x + 3, y + 4, width, height, 8, 8);
        g.setColor(new Color(43, 36, 27, 248));
        g.fillRoundRect(x, y, width, height, 8, 8);
        g.setColor(new Color(30, 24, 18));
        g.fillRoundRect(x + 5, y + 6, width - 10, height - 12, 5, 5);
        g.setColor(new Color(93, 76, 49));
        g.setStroke(new BasicStroke(2f));
        g.drawRoundRect(x + 1, y + 1, width - 3, height - 3, 8, 8);
        g.setColor(new Color(181, 151, 91));
        g.setStroke(new BasicStroke(1f));
        g.drawRoundRect(x + 4, y + 4, width - 9, height - 9, 5, 5);
        g.setColor(tierColor);
        g.fillRect(x + 8, y + 7, width - 16, 2);
        g.setColor(new Color(113, 91, 54));
        g.drawLine(x + 44, y + 13, x + 44, y + height - 13);
        g.drawLine(x + width - 47, y + 13, x + width - 47, y + height - 13);
        drawRivet(g, x + 7, y + 7);
        drawRivet(g, x + width - 8, y + 7);
        drawRivet(g, x + 7, y + height - 8);
        drawRivet(g, x + width - 8, y + height - 8);

        g.drawImage(spoonIcons.get(record.getTier()), x + 8, y + 24, null);
        if (cachedItemId != record.getDisplayItemId())
        {
            cachedItemId = record.getDisplayItemId();
            cachedItemImage = ImageUtil.resizeImage(itemManager.getImage(cachedItemId), 36, 36);
        }
        if (cachedItemImage != null)
        {
            g.drawImage(cachedItemImage, x + width - 41, y + 22, null);
        }

        int textLeft = x + 50;
        int textRight = x + width - 50;
        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(16f));
        String title = record.getTier() == null ? "Mystery spoon" : record.getTier().getDisplayName();
        drawFitted(g, title, textLeft, textRight, y + 24, tierColor);
        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(15f));
        drawFitted(g, record.getItemName(), textLeft, textRight, y + 44,
            new Color(255, 152, 31));
        g.setFont(FontManager.getRunescapeSmallFont().deriveFont(13f));
        String details = record.getActivityName() + "  |  "
            + (record.getObtainedKillCount() == null ? "Count ?" : "Count " + record.getObtainedKillCount())
            + (record.getEffectiveDenominator() == null ? "" : String.format("  |  1/%.0f", record.getEffectiveDenominator()));
        drawFitted(g, details, textLeft, textRight, y + 62, new Color(205, 190, 163));
        g.dispose();
        return null;
    }

    private static void drawRivet(Graphics2D g, int x, int y)
    {
        g.setColor(new Color(38, 30, 20));
        g.fillOval(x - 2, y - 2, 5, 5);
        g.setColor(new Color(191, 158, 91));
        g.fillOval(x - 1, y - 1, 3, 3);
    }

    private static void drawFitted(Graphics2D g, String text, int left, int right, int baseline, Color color)
    {
        int textWidth = g.getFontMetrics().stringWidth(text);
        int available = right - left;
        if (textWidth > available && text.length() > 3)
        {
            while (textWidth > available && text.length() > 3)
            {
                text = text.substring(0, text.length() - 2);
                textWidth = g.getFontMetrics().stringWidth(text + "...");
            }
            text += "...";
            textWidth = g.getFontMetrics().stringWidth(text);
        }
        int textX = left + Math.max(0, (available - textWidth) / 2);
        g.setColor(Color.BLACK);
        g.drawString(text, textX + 1, baseline + 1);
        g.setColor(color);
        g.drawString(text, textX, baseline);
    }
}

package com.spoontracker;

import java.util.Arrays;

public final class DropMechanic
{
    public enum Kind
    {
        FIXED,
        INDEPENDENT_ROLLS,
        COMPOSITE,
        GUARANTEED,
        VARIABLE,
        DETERMINISTIC,
        UNSUPPORTED
    }

    private final Kind kind;
    private final double[] probabilities;
    private final int rolls;
    private final int guarantee;
    private final String metadataKey;
    private final String reason;

    private DropMechanic(Kind kind, double[] probabilities, int rolls, int guarantee,
        String metadataKey, String reason)
    {
        this.kind = kind;
        this.probabilities = probabilities;
        this.rolls = rolls;
        this.guarantee = guarantee;
        this.metadataKey = metadataKey;
        this.reason = reason;
    }

    public static DropMechanic fixedDenominator(double denominator)
    {
        return fixedProbability(1.0 / denominator);
    }

    public static DropMechanic fixedProbability(double probability)
    {
        return new DropMechanic(Kind.FIXED, new double[]{probability}, 1, 0, null, null);
    }

    public static DropMechanic independentRolls(double perRollProbability, int rolls)
    {
        return new DropMechanic(Kind.INDEPENDENT_ROLLS,
            new double[]{perRollProbability}, rolls, 0, null, null);
    }

    public static DropMechanic composite(double... probabilities)
    {
        return new DropMechanic(Kind.COMPOSITE,
            Arrays.copyOf(probabilities, probabilities.length), 1, 0, null, null);
    }

    public static DropMechanic guaranteed(double randomProbability, int guarantee)
    {
        return new DropMechanic(Kind.GUARANTEED,
            new double[]{randomProbability}, 1, guarantee, null, null);
    }

    public static DropMechanic variable(String metadataKey)
    {
        return new DropMechanic(Kind.VARIABLE, new double[0], 1, 0, metadataKey, null);
    }

    public static DropMechanic deterministic(String reason)
    {
        return new DropMechanic(Kind.DETERMINISTIC, new double[0], 1, 0, null, reason);
    }

    public static DropMechanic unsupported(String reason)
    {
        return new DropMechanic(Kind.UNSUPPORTED, new double[0], 1, 0, null, reason);
    }

    public RateEvaluation evaluate(DropContext context)
    {
        switch (kind)
        {
            case FIXED:
                return fromEncounterProbability(probabilities[0], "Fixed rate");
            case INDEPENDENT_ROLLS:
                return fromEncounterProbability(1.0 - Math.pow(1.0 - probabilities[0], rolls),
                    rolls + " independent rolls");
            case COMPOSITE:
                double miss = 1.0;
                for (double probability : probabilities)
                {
                    miss *= 1.0 - probability;
                }
                return fromEncounterProbability(1.0 - miss, "Composite sources");
            case GUARANTEED:
                if (!validProbability(probabilities[0]) || guarantee < 1)
                {
                    return RateEvaluation.unavailable("Guaranteed drop", "Invalid guaranteed-drop definition");
                }
                double expected = (1.0 - Math.pow(1.0 - probabilities[0], guarantee)) / probabilities[0];
                return RateEvaluation.exact(expected, "Random drop; guaranteed by " + guarantee);
            case VARIABLE:
                Double probability = context.getRateMetadata().get(metadataKey);
                return probability == null
                    ? RateEvaluation.unavailable("Variable rate", "Missing exact run probability")
                    : fromEncounterProbability(probability, "Exact run probability");
            case DETERMINISTIC:
                return RateEvaluation.unavailable("Deterministic reward", reason);
            default:
                return RateEvaluation.unavailable("Unsupported mechanic", reason);
        }
    }

    private static RateEvaluation fromEncounterProbability(double probability, String label)
    {
        return validProbability(probability)
            ? RateEvaluation.exact(1.0 / probability, label)
            : RateEvaluation.unavailable(label, "Invalid probability");
    }

    private static boolean validProbability(double probability)
    {
        return Double.isFinite(probability) && probability > 0 && probability <= 1;
    }

    public Kind getKind() { return kind; }
}

package com.spoontracker;

import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.OptionalDouble;
import java.util.Set;
import net.runelite.client.game.ItemStack;

public final class TrackingEngine
{
    private final RateCalculator rateCalculator;
    private final Clock clock;

    public TrackingEngine(RateCalculator rateCalculator, Clock clock)
    {
        this.rateCalculator = rateCalculator;
        this.clock = clock;
    }

    public List<TrackedUnique> recognize(BossDefinition boss, Collection<ItemStack> items,
        Integer killCount, DropContext context, Collection<TrackedUnique> existing)
    {
        return recognizeActivity(boss, items, killCount, context, existing);
    }

    public List<TrackedUnique> recognizeActivity(ActivityDefinition activity, Collection<ItemStack> items,
        Integer completionCount, DropContext context, Collection<TrackedUnique> existing)
    {
        Set<String> known = new HashSet<>();
        for (TrackedUnique record : existing)
        {
            known.add(record.identityKey());
        }

        List<TrackedUnique> result = new ArrayList<>();
        Set<Integer> seenInDrop = new HashSet<>();
        for (ItemStack item : items)
        {
            Optional<UniqueDefinition> definition = activity.findUnique(item.getId());
            if (!definition.isPresent())
            {
                continue;
            }
            UniqueDefinition unique = definition.get();
            String identity = activity.getKey() + ":" + unique.getCanonicalItemId();
            if (known.contains(identity) || !seenInDrop.add(unique.getCanonicalItemId()))
            {
                continue;
            }

            RateEvaluation evaluation = activity instanceof BossDefinition
                ? rateCalculator.evaluate((BossDefinition) activity, unique, context)
                : new FirstAcquisitionCalculator().evaluate(activity, unique, context);
            OptionalDouble denominator = evaluation.getExpectedCompletions();
            Double expected = denominator.isPresent() ? denominator.getAsDouble() : null;
            SpoonTier tier = completionCount != null && expected != null
                ? SpoonTier.from(completionCount, expected).orElse(null)
                : null;
            Instant now = clock.instant();
            TrackedUnique tracked = new TrackedUnique(activity.getKey(), activity.getName(),
                unique.getCanonicalItemId(), item.getId(), unique.getName(), completionCount,
                expected, tier, now, BossCatalog.VERSION, evaluation.getMechanic(),
                evaluation.getConfidence(), evaluation.getReason());
            result.add(tracked);
            known.add(identity);
        }
        return result;
    }
}

package com.spoontracker;

import com.peanubnutter.collectionlogluck.luck.LogItemInfo;
import com.peanubnutter.collectionlogluck.luck.RollInfo;
import com.peanubnutter.collectionlogluck.luck.drop.AbstractDrop;
import com.peanubnutter.collectionlogluck.luck.drop.DeterministicDrop;
import com.peanubnutter.collectionlogluck.luck.drop.DropLuck;
import com.peanubnutter.collectionlogluck.luck.drop.DupeProtectedFirstSetBinomialDrop;
import com.peanubnutter.collectionlogluck.luck.drop.DupeProtectedSetBinomialDrop;
import com.peanubnutter.collectionlogluck.luck.drop.GuaranteedOnceBinomialDrop;
import com.peanubnutter.collectionlogluck.luck.drop.HiddenShardDrop;
import com.peanubnutter.collectionlogluck.luck.drop.SinglePityBinomialDrop;

final class ReferenceMechanicAdapter
{
    private ReferenceMechanicAdapter() { }

    static DropMechanic forItem(int itemId, String activityKey)
    {
        return forItemSelector(itemId, activityKey);
    }

    static DropMechanic forItemSource(int itemId, String source)
    {
        return forItemSelector(itemId, source);
    }

    private static DropMechanic forItemSelector(int itemId, String selector)
    {
        LogItemInfo info = LogItemInfo.findByItemId(itemId);
        if (info == null)
        {
            return DropMechanic.unsupported("Item is not in the pinned probability catalog");
        }
        DropLuck drop = info.getDropProbabilityDistribution();
        if (drop instanceof DeterministicDrop)
        {
            return DropMechanic.deterministic("Not an RNG reward");
        }
        if (!(drop instanceof AbstractDrop))
        {
            return DropMechanic.unsupported(drop.getClass().getSimpleName());
        }
        AbstractDrop abstractDrop = (AbstractDrop) drop;
        if (!abstractDrop.getConfigOptions().isEmpty())
        {
            return DropMechanic.variable("item." + itemId + ".probability");
        }
        if (drop instanceof DupeProtectedSetBinomialDrop
            || drop instanceof DupeProtectedFirstSetBinomialDrop
            || drop instanceof SinglePityBinomialDrop)
        {
            return DropMechanic.unsupported("Account progression state is required");
        }
        if (abstractDrop.getRollInfos().isEmpty())
        {
            return DropMechanic.unsupported("No attributable roll source");
        }
        RollInfo selected = selectRoll(abstractDrop, selector);
        if (selected == null)
        {
            return DropMechanic.variable("item." + itemId + ".probability");
        }
        double probability = selected.getDropChancePerRoll();
        int rolls = selected.getRollsPerKc();
        if (drop instanceof GuaranteedOnceBinomialDrop)
        {
            return DropMechanic.guaranteed(1.0 - Math.pow(1.0 - probability, rolls),
                ((GuaranteedOnceBinomialDrop) drop).getDropGuaranteedOnKc());
        }
        if (drop instanceof HiddenShardDrop)
        {
            double expected = ((HiddenShardDrop) drop).getShardsRequired()
                / (probability * Math.max(1, rolls));
            return DropMechanic.fixedDenominator(expected);
        }
        return DropMechanic.independentRolls(probability, Math.max(1, rolls));
    }

    private static RollInfo selectRoll(AbstractDrop drop, String selector)
    {
        if (drop.getRollInfos().size() == 1) return drop.getRollInfos().get(0);
        String normalizedActivity = BossDefinition.normalize(selector).replaceAll("[^a-z0-9]", "")
            .replace("treasuretrails", "").replace("cluescroll", "");
        for (RollInfo roll : drop.getRollInfos())
        {
            String source = roll.getDropSource().name().toLowerCase().replace("_", "");
            String baseSource = source.replace("kills", "").replace("cluescompleted", "")
                .replace("completions", "").replace("completioncount", "");
            if (source.contains(normalizedActivity) || normalizedActivity.contains(baseSource)
                || baseSource.contains(normalizedActivity))
            {
                return roll;
            }
        }
        return null;
    }
}

package com.spoontracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;

/**
 * Curated collection-log drop data. Rates are a reviewed 2026-07-22 snapshot of
 * the OSRS Wiki drop tables. Variable raid rates are deliberately left for the
 * run-specific calculator and are never guessed from a static average.
 */
public final class BossCatalog
{
    public static final String VERSION = "2026-07-22-full-log";
    private final List<BossDefinition> bosses;

    public BossCatalog()
    {
        bosses = Collections.unmodifiableList(build());
        validate();
    }

    public List<BossDefinition> getBosses()
    {
        return bosses;
    }

    public Optional<BossDefinition> findBySource(String source)
    {
        return bosses.stream().filter(boss -> boss.matchesSource(source)).findFirst();
    }

    public Optional<BossDefinition> findByKey(String key)
    {
        return bosses.stream().filter(boss -> boss.getKey().equals(key)).findFirst();
    }

    public void validate()
    {
        Set<String> keys = new HashSet<>();
        java.util.Map<String, String> aliases = new java.util.HashMap<>();
        for (BossDefinition boss : bosses)
        {
            if (!keys.add(boss.getKey()))
            {
                throw new IllegalStateException("Duplicate boss key: " + boss.getKey());
            }
            if (boss.getAliases().isEmpty())
            {
                throw new IllegalStateException("Boss has no aliases: " + boss.getKey());
            }
            for (String alias : boss.getAliases())
            {
                String owner = aliases.put(alias, boss.getKey());
                if (owner != null && !owner.equals(boss.getKey()))
                {
                    throw new IllegalStateException("Source alias belongs to two activities: " + alias);
                }
            }
            Set<Integer> canonicalIds = new HashSet<>();
            Set<Integer> allIds = new HashSet<>();
            for (UniqueDefinition unique : boss.getUniques())
            {
                if (unique.getCanonicalItemId() <= 0 || unique.getName().trim().isEmpty())
                {
                    throw new IllegalStateException("Invalid unique in " + boss.getKey());
                }
                if (unique.getDropMechanic() == null)
                {
                    throw new IllegalStateException("Missing drop mechanic for " + unique.getName());
                }
                if (!canonicalIds.add(unique.getCanonicalItemId()))
                {
                    throw new IllegalStateException("Duplicate canonical item in " + boss.getKey());
                }
                for (int id : unique.getItemIds())
                {
                    if (!allIds.add(id))
                    {
                        throw new IllegalStateException("Item variant belongs to two uniques in " + boss.getKey());
                    }
                }
            }
        }
    }

    private static BossDefinition fixed(String key, String name, String[] aliases, UniqueDefinition... uniques)
    {
        return new BossDefinition(key, name, false, Arrays.asList(aliases), Arrays.asList(uniques));
    }

    private static BossDefinition variable(String key, String name, String[] aliases, UniqueDefinition... uniques)
    {
        return new BossDefinition(key, name, true, Arrays.asList(aliases), Arrays.asList(uniques));
    }

    private static UniqueDefinition u(int id, String name, double denominator, int... variants)
    {
        return new UniqueDefinition(id, name, denominator, variants);
    }

    private static UniqueDefinition m(int id, String name, DropMechanic mechanic, int... variants)
    {
        return new UniqueDefinition(id, name, mechanic, variants);
    }

    private static List<BossDefinition> build()
    {
        List<BossDefinition> b = new ArrayList<>();
        b.add(fixed("zulrah", "Zulrah", new String[]{"Zulrah"},
