package com.spoontracker;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.config.ConfigManager;

final class PendingAttributionStore
{
    private static final String KEY = "pending_attributions_v1";
    private final ConfigManager configManager;
    private final Gson gson;

    PendingAttributionStore(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    List<PendingAttribution> load()
    {
        String value = configManager.getRSProfileConfiguration(SpoonTrackerStore.GROUP, KEY);
        if (value == null || value.trim().isEmpty()) return new ArrayList<>();
        try
        {
            PendingAttribution[] stored = gson.fromJson(value, PendingAttribution[].class);
            if (stored == null) return new ArrayList<>();
            List<PendingAttribution> result = new ArrayList<>(Arrays.asList(stored));
            result.removeIf(pending -> pending == null || pending.getItemId() <= 0
                || pending.getActivityKeys() == null || pending.getActivityKeys().isEmpty());
            return result;
        }
        catch (JsonParseException | IllegalStateException ex)
        {
            return new ArrayList<>();
        }
    }

    void save(List<PendingAttribution> pending)
    {
        configManager.setRSProfileConfiguration(SpoonTrackerStore.GROUP, KEY,
            gson.toJson(pending == null ? Collections.emptyList() : pending));
    }

    void reset() { configManager.unsetRSProfileConfiguration(SpoonTrackerStore.GROUP, KEY); }
}

