        recordsPanel.setLayout(new BoxLayout(recordsPanel, BoxLayout.Y_AXIS));
        recordsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JScrollPane scroll = new JScrollPane(recordsPanel);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        luckPanel.setLayout(new BoxLayout(luckPanel, BoxLayout.Y_AXIS));
        luckPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JScrollPane luckScroll = new JScrollPane(luckPanel);
        luckScroll.setBorder(BorderFactory.createEmptyBorder());
        luckScroll.getVerticalScrollBar().setUnitIncrement(16);
        JTabbedPane tabs = new JTabbedPane();
        tabs.addTab("Earned", scroll);
        tabs.addTab("Log Luck", luckScroll);
        add(tabs, BorderLayout.CENTER);

        JPanel actions = new JPanel(new GridLayout(7, 1, 0, 5));
        actions.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JButton copyCard = new JButton("Copy latest share card");
        copyCard.setToolTipText("Copy a Discord-ready image of the latest spoon to the clipboard");
        copyCard.addActionListener(e -> copyCardAction.run());
        actions.add(copyCard);

        JButton saveCard = new JButton("Save latest share card");
        saveCard.setToolTipText("Save the latest spoon card as a PNG in RuneLite's screenshot folder");
        saveCard.addActionListener(e -> saveCardAction.run());
        actions.add(saveCard);

        JButton refreshLuck = new JButton("Refresh Log Luck");
        refreshLuck.setToolTipText("Capture quantities and counters from the open Collection Log page");
        refreshLuck.addActionListener(e -> refreshLuckAction.run());
        actions.add(refreshLuck);

        JButton clearLuck = new JButton("Clear Log Luck session");
        clearLuck.setToolTipText("Forget non-persistent historical preview data for this session");
        clearLuck.addActionListener(e -> clearLuckAction.run());
        actions.add(clearLuck);

        JButton resolvePending = new JButton("Resolve pending drop");
        resolvePending.setToolTipText("Choose the Collection Log activity for an ambiguous observed item");
        resolvePending.addActionListener(e -> resolvePendingAction.run());
        actions.add(resolvePending);

        JButton clearPending = new JButton("Clear pending drops");
        clearPending.setToolTipText("Dismiss every unresolved ambiguous Collection Log notification");
        clearPending.addActionListener(e -> {
            int answer = JOptionPane.showConfirmDialog(this,
                "Dismiss all pending activity attributions?", "Clear Pending Drops",
                JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
            if (answer == JOptionPane.YES_OPTION) clearPendingAction.run();
        });
        actions.add(clearPending);

        JButton reset = new JButton("Reset tracked spoons");
        reset.addActionListener(e -> {
            int answer = JOptionPane.showConfirmDialog(this,
                "Delete all Spoon Tracker records for this RuneScape profile?",
                "Reset Spoon Tracker", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
            if (answer == JOptionPane.YES_OPTION)
            {
                resetAction.run();
            }
        });
        actions.add(reset);
        add(actions, BorderLayout.SOUTH);
        refresh(new ArrayList<>());
    }

    public SpoonTrackerPanel(ItemManager itemManager, Runnable copyCardAction,
        Runnable saveCardAction, Runnable resetAction)
    {
        this(itemManager, copyCardAction, saveCardAction,
            () -> { }, () -> { }, () -> { }, () -> { }, resetAction);
    }

    public void refresh(List<TrackedUnique> records)
    {
        refresh(records, Collections.emptyList(), "Enable Historical Log Luck to begin", 0);
    }

    public void refresh(List<TrackedUnique> records, List<HistoricalLuckResult> luckResults,
        String historicalStatus)
    {
        refresh(records, luckResults, historicalStatus, 0);
    }

    public void refresh(List<TrackedUnique> records, List<HistoricalLuckResult> luckResults,
        String historicalStatus, int pendingCount)
    {
        total.setText(Integer.toString(records.size()));
        Map<SpoonTier, Integer> counts = new EnumMap<>(SpoonTier.class);
        for (SpoonTier tier : SpoonTier.values())
        {
            counts.put(tier, 0);
        }
        for (TrackedUnique record : records)
        {
            if (record.getTier() != null)
            {
                counts.put(record.getTier(), counts.get(record.getTier()) + 1);
            }
        }
        tierGrid.removeAll();
        for (SpoonTier tier : SpoonTier.values())
        {
            JLabel label = new JLabel(Integer.toString(counts.get(tier)), SwingConstants.CENTER);
            label.setIcon(new javax.swing.ImageIcon(spoonIcons.get(tier)));
            label.setIconTextGap(2);
            label.setForeground(tier.getColor());
            label.setToolTipText(tier.getDisplayName());
            tierGrid.add(label);
        }

        recordsPanel.removeAll();
        if (pendingCount > 0)
        {
            pendingStatus.setText(pendingCount + " drop" + (pendingCount == 1 ? "" : "s")
                + " waiting for activity attribution");
            pendingStatus.setForeground(new Color(255, 194, 51));
            pendingStatus.setBorder(BorderFactory.createEmptyBorder(6, 4, 8, 4));
            pendingStatus.setAlignmentX(Component.CENTER_ALIGNMENT);
            recordsPanel.add(pendingStatus);
        }
        List<TrackedUnique> sorted = new ArrayList<>(records);
        sorted.sort(Comparator.comparing(TrackedUnique::getObtainedAt,
            Comparator.nullsLast(Comparator.reverseOrder())));
        if (sorted.isEmpty())
        {
            JLabel empty = new JLabel("Your cabinet is waiting for loot!", SwingConstants.CENTER);
            empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            empty.setBorder(BorderFactory.createEmptyBorder(24, 4, 4, 4));
            empty.setAlignmentX(Component.CENTER_ALIGNMENT);
            recordsPanel.add(empty);
        }
        for (TrackedUnique record : sorted)
        {
            recordsPanel.add(recordRow(record));
            recordsPanel.add(Box.createVerticalStrut(5));
        }

        luckPanel.removeAll();
        luckStatus.setText(historicalStatus == null ? "No historical data loaded" : historicalStatus);
        luckStatus.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        luckStatus.setBorder(BorderFactory.createEmptyBorder(8, 4, 10, 4));
        luckStatus.setAlignmentX(Component.CENTER_ALIGNMENT);
        luckPanel.add(luckStatus);
        for (HistoricalLuckResult result : luckResults)
        {
            luckPanel.add(luckRow(result));
            luckPanel.add(Box.createVerticalStrut(5));
        }
        revalidate();
        repaint();
    }

    private JPanel luckRow(HistoricalLuckResult result)
    {
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 62));
        JLabel icon = new JLabel(new javax.swing.ImageIcon(itemManager.getImage(result.getItemId())));
        icon.setPreferredSize(new Dimension(40, 40));
        row.add(icon, BorderLayout.WEST);

        JPanel text = new JPanel();
        text.setOpaque(false);
        text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
        JLabel item = new JLabel(result.getItemName() + "  x" + result.getQuantity());
        item.setForeground(result.getPreviewTier() == null
            ? ColorScheme.LIGHT_GRAY_COLOR : result.getPreviewTier().getColor());
        String details;
        if (result.getOverallLuck() == null)
        {
            details = "Unavailable • " + result.getDetail();
        }
        else
        {
            details = String.format("Preview • %.1f%% overall • %s",
                result.getOverallLuck() * 100,
                result.getConfidence() == RateConfidence.ESTIMATED ? "Estimated" : "Exact");
        }
        JLabel detail = new JLabel(details);
        detail.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        detail.setToolTipText(result.getMechanic() + " • " + result.getDetail());
        text.add(item);
        text.add(detail);
        row.add(text, BorderLayout.CENTER);
        if (result.getPreviewTier() != null)
        {
            JLabel spoon = new JLabel(new javax.swing.ImageIcon(spoonIcons.get(result.getPreviewTier())));
            spoon.setToolTipText("Preview " + result.getPreviewTier().getDisplayName());
            row.add(spoon, BorderLayout.EAST);
        }
        return row;
    }

    private JPanel recordRow(TrackedUnique record)
    {
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 58));
        JLabel icon = new JLabel();
        icon.setPreferredSize(new Dimension(40, 40));
        icon.setIcon(new javax.swing.ImageIcon(itemManager.getImage(record.getDisplayItemId())));
        row.add(icon, BorderLayout.WEST);

        JPanel text = new JPanel();
        text.setOpaque(false);
        text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
        JLabel item = new JLabel(record.getItemName());
        item.setForeground(record.getTier() == null ? new Color(190, 150, 255) : record.getTier().getColor());
        JLabel details = new JLabel(record.getActivityName() + " • "
            + (record.getObtainedKillCount() == null ? "Count ?" : "Count " + record.getObtainedKillCount()));
        details.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        details.setToolTipText(record.getUngradedReason() == null
            ? record.getRateMechanic() : record.getRateMechanic() + " • " + record.getUngradedReason());
        text.add(item);
        text.add(details);
        row.add(text, BorderLayout.CENTER);
        return row;
    }

}

