    SpoonIconSet(int size)
    {
        mysteryIcon = load("spoon.png", size);
        for (SpoonTier tier : SpoonTier.values())
        {
            icons.put(tier, load(tier.getIconResource(), size));
        }
    }

    BufferedImage get(SpoonTier tier)
    {
        return tier == null ? mysteryIcon : icons.get(tier);
    }

    private static BufferedImage load(String resource, int size)
    {
        return ImageUtil.resizeImage(
            ImageUtil.loadImageResource(SpoonTrackerPlugin.class, resource), size, size);
    }
}

package com.spoontracker;

import java.time.Instant;

public final class TrackedUnique
{
    private int schemaVersion;
    private String bossKey;
    private String bossName;
    private int canonicalItemId;
    private int displayItemId;
    private String itemName;
    private Integer obtainedKillCount;
    private Double effectiveDenominator;
    private SpoonTier tier;
    private Instant obtainedAt;
    private String catalogVersion;
    private String activityKey;
    private String activityName;
    private String rateMechanic;
    private RateConfidence rateConfidence;
    private String ungradedReason;

    public TrackedUnique()
    {
        // Gson constructor.
    }

    public TrackedUnique(String bossKey, String bossName, int canonicalItemId, int displayItemId,
        String itemName, Integer obtainedKillCount, Double effectiveDenominator, SpoonTier tier,
        Instant obtainedAt, String catalogVersion)
    {
        this(bossKey, bossName, canonicalItemId, displayItemId, itemName, obtainedKillCount,
            effectiveDenominator, tier, obtainedAt, catalogVersion,
            effectiveDenominator == null ? null : "Legacy fixed rate",
            effectiveDenominator == null ? RateConfidence.UNAVAILABLE : RateConfidence.EXACT, null);
    }

    public TrackedUnique(String activityKey, String activityName, int canonicalItemId, int displayItemId,
        String itemName, Integer obtainedKillCount, Double effectiveDenominator, SpoonTier tier,
        Instant obtainedAt, String catalogVersion, String rateMechanic,
        RateConfidence rateConfidence, String ungradedReason)
    {
        this.schemaVersion = 2;
        this.activityKey = activityKey;
        this.activityName = activityName;
        this.bossKey = activityKey;
        this.bossName = activityName;
        this.canonicalItemId = canonicalItemId;
        this.displayItemId = displayItemId;
        this.itemName = itemName;
        this.obtainedKillCount = obtainedKillCount;
        this.effectiveDenominator = effectiveDenominator;
        this.tier = tier;
        this.obtainedAt = obtainedAt;
