        this.rateMechanic = rateMechanic;
        this.rateConfidence = rateConfidence;
        this.ungradedReason = ungradedReason;
    }

    public int getSchemaVersion() { return schemaVersion; }
    public String getBossKey() { return getActivityKey(); }
    public String getBossName() { return getActivityName(); }
    public String getActivityKey() { return activityKey == null ? bossKey : activityKey; }
    public String getActivityName() { return activityName == null ? bossName : activityName; }
    public int getCanonicalItemId() { return canonicalItemId; }
    public int getDisplayItemId() { return displayItemId; }
    public String getItemName() { return itemName; }
    public Integer getObtainedKillCount() { return obtainedKillCount; }
    public Double getEffectiveDenominator() { return effectiveDenominator; }
    public SpoonTier getTier() { return tier; }
    public Instant getObtainedAt() { return obtainedAt; }
    public String getCatalogVersion() { return catalogVersion; }
    public String getRateMechanic() { return rateMechanic; }
    public RateConfidence getRateConfidence() { return rateConfidence; }
    public String getUngradedReason() { return ungradedReason; }

    public String identityKey()
    {
        return getActivityKey() + ":" + canonicalItemId;
    }
}

