@PluginDescriptor(
    name = "Spoon Tracker",
    description = "Earn spoons for new Collection Log drops and preview historical log luck",
    tags = {"loot", "boss", "unique", "collection log", "spoon", "luck", "clues", "minigames"}
)
public class SpoonTrackerPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(SpoonTrackerPlugin.class);
    @Inject private Client client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private OverlayManager overlayManager;
    @Inject private TooltipManager tooltipManager;
    @Inject private ItemManager itemManager;
    @Inject private ConfigManager configManager;
    @Inject private ClientThread clientThread;
    @Inject private SpoonTrackerConfig config;
    @Inject private Gson gson;
    @Inject private HiscoreClient hiscoreClient;

    private BossCatalog catalog;
    private KillCountCorrelator correlator;
    private TrackingEngine trackingEngine;
    private SpoonTrackerStore store;
    private CelebrationManager celebrations;
    private SpoonCelebrationOverlay overlay;
    private CollectionLogSpoonOverlay collectionLogOverlay;
    private SpoonTrackerPanel panel;
    private NavigationButton navigationButton;
    private SpoonShareCardRenderer shareCardRenderer;
    private volatile TrackedUnique latestShareRecord;
    private List<TrackedUnique> records = new ArrayList<>();
    private boolean rewardWidgetHandled;
    private FullCollectionLogCatalog fullCatalog;
    private CollectionLogCaptureService collectionLogCapture;
    private HistoricalLuckCalculator historicalLuckCalculator;
    private CollectionLogLuckConfig historicalAssumptions;
    private HistoricalLogSnapshot historicalSnapshot;
    private List<HistoricalLuckResult> historicalResults = new ArrayList<>();
    private String historicalStatus = "Enable Historical Log Luck to begin";
    private PendingAttributionStore pendingStore;
    private List<PendingAttribution> pendingAttributions = new ArrayList<>();
    private String lastNotificationIdentity;
    private ActivityCountCorrelator activityCorrelator;

    @Provides
    SpoonTrackerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(SpoonTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        catalog = new BossCatalog();
        fullCatalog = new FullCollectionLogCatalog(gson);
        correlator = new KillCountCorrelator(catalog);
        activityCorrelator = new ActivityCountCorrelator();
        trackingEngine = new TrackingEngine(new RateCalculator(), Clock.systemUTC());
        store = new SpoonTrackerStore(configManager, gson);
        pendingStore = new PendingAttributionStore(configManager, gson);
        celebrations = new CelebrationManager(Clock.systemUTC());
        overlay = new SpoonCelebrationOverlay(client, itemManager, config, celebrations);
        collectionLogOverlay = new CollectionLogSpoonOverlay(client, config, catalog,
            this::collectionLogRecords, this::historicalLuckResults, tooltipManager);
        shareCardRenderer = new SpoonShareCardRenderer();
        collectionLogCapture = new CollectionLogCaptureService(Clock.systemUTC());
        historicalLuckCalculator = new HistoricalLuckCalculator();
        historicalAssumptions = new SpoonHistoricalAssumptions(config);
        panel = new SpoonTrackerPanel(itemManager, this::copyLatestShareCard,
            this::saveLatestShareCard,
            this::manualRefreshHistoricalLuck, this::clearHistoricalSession,
            this::resolvePendingAttribution, this::clearPendingAttributions, this::resetRecords);
        overlayManager.add(overlay);
        overlayManager.add(collectionLogOverlay);

        BufferedImage icon = ImageUtil.resizeImage(
            ImageUtil.loadImageResource(getClass(), "spoon.png"), 32, 32);
        navigationButton = NavigationButton.builder()
            .tooltip("Spoon Tracker")
            .icon(icon)
            .priority(6)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);
        loadProfile();
        preloadHiscoreKillCounts();
        LOG.info("Spoon Tracker started with {} tracked boss definitions and {} full-log items (catalog {})",
            catalog.getBosses().size(), fullCatalog.size(), fullCatalog.getVersion());
    }

    @Override
    protected void shutDown()
    {
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
        }
        if (overlay != null)
        {
            overlayManager.remove(overlay);
        }
        if (collectionLogOverlay != null)
        {
            overlayManager.remove(collectionLogOverlay);
        }
        if (correlator != null)
        {
            correlator.clear();
        }
        if (activityCorrelator != null) activityCorrelator.clear();
        if (celebrations != null)
        {
            celebrations.clear();
        }
        rewardWidgetHandled = false;
        records = new ArrayList<>();
        latestShareRecord = null;
        pendingAttributions = new ArrayList<>();
        lastNotificationIdentity = null;
        clearHistoricalSession();
    }

    @Subscribe
    public void onServerNpcLoot(ServerNpcLoot event)
    {
        String source = Text.removeTags(event.getComposition().getName());
        queueDrop(source, event.getItems(), Collections.emptyMap());
    }

    @Subscribe
    public void onLootReceived(LootReceived event)
    {
        List<ItemStack> items = new ArrayList<>();
        for (Object item : event.getItems())
        {
            if (item instanceof ItemStack)
            {
                items.add((ItemStack) item);
            }
        }
        queueDrop(event.getName(), items, extractRateMetadata(event.getMetadata()));
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE
            && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }
        correlator.parseKillCount(event.getMessage(), client.getTickCount());
        activityCorrelator.parse(event.getMessage(), client.getTickCount());
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        for (KillCountCorrelator.PendingDrop pending : correlator.drainReady(client.getTickCount()))
        {
            List<TrackedUnique> additions = trackingEngine.recognize(pending.getBoss(), pending.getItems(),
                pending.getKillCount(), pending.getContext(), records);
            for (TrackedUnique addition : additions)
            {
                records.add(addition);
                if (config.celebrationOverlay())
                {
                    celebrations.enqueue(addition);
                }
                announce(addition);
            }
            if (!additions.isEmpty())
            {
                store.save(records);
                refreshPanel();
            }
        }
        for (ActivityCountCorrelator.Pending pending : activityCorrelator.drainReady(client.getTickCount()))
        {
            finalizeGenericDrop(pending.getActivity(), pending.getItemId(), pending.getCount(),
                pending.getContext());
        }
        if (client.getTickCount() % 5 == 0)
        {
            captureOpenCollectionLogPage();
        }
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        correlator.clear();
        activityCorrelator.clear();
        celebrations.clear();
        clearHistoricalSession();
        loadProfile();
        preloadHiscoreKillCounts();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (SpoonTrackerStore.GROUP.equals(event.getGroup()))
        {
            if ("historicalLuck".equals(event.getKey()))
            {
                if (config.historicalLuck()) refreshHistoricalLuck();
                else clearHistoricalSession();
            }
            refreshPanel();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
        {
            rewardWidgetHandled = false;
        }
        else if (event.getGameState() == GameState.LOGGED_IN)
        {
            preloadHiscoreKillCounts();
            try
            {
                int currentItems = fullCatalog.loadGameCollectionLog(client, itemManager);
                LOG.debug("Resolved {} current Collection Log items from the game cache", currentItems);
            }
            catch (RuntimeException ex)
            {
                LOG.warn("Unable to resolve the current Collection Log layout from the game cache", ex);
            }
            if (config.historicalLuck())
            {
                refreshHistoricalLuck();
            }
        }
    }

    /**
     * Direct reward-container handling keeps raid tracking operational even if the core Loot Tracker
     * panel is disabled. The generalized LootReceived path remains useful for other supported events;
     * identity-level duplicate suppression makes receiving both paths harmless.
     */
    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.NOTIFICATION_DISPLAY)
        {
            handleCollectionLogNotification();
            return;
        }
        if (rewardWidgetHandled)
        {
            return;
        }
        String source;
        int containerId;
        Map<String, Double> metadata = new HashMap<>();
        switch (event.getGroupId())
        {
            case InterfaceID.RAIDS_REWARDS:
                source = "Chambers of Xeric";
                containerId = InventoryID.RAIDS_REWARDS;
                break;
            case InterfaceID.TOB_CHESTS:
                source = "Theatre of Blood";
                containerId = InventoryID.TOB_CHESTS;
                break;
            case InterfaceID.TOA_CHESTS:
                source = "Tombs of Amascut";
                containerId = InventoryID.TOA_CHESTS;
                metadata.put("raid.level", (double) client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL));
                metadata.put("raid.damage", (double) client.getVarbitValue(VarbitID.TOA_DAMAGE_DONE));
                break;
            default:
                return;
        }
        ItemContainer container = client.getItemContainer(containerId);
        if (container == null)
        {
            return;
        }
        List<ItemStack> items = new ArrayList<>();
        for (Item item : container.getItems())
        {
            if (item.getId() >= 0 && item.getQuantity() > 0)
            {
                items.add(new ItemStack(item.getId(), item.getQuantity()));
            }
        }
        rewardWidgetHandled = true;
        queueDrop(source, items, metadata);
    }

    private void queueDrop(String source, Collection<ItemStack> items, Map<String, Double> metadata)
    {
        if (source == null || items == null || items.isEmpty())
        {
            return;
        }
        Optional<BossDefinition> boss = catalog.findBySource(source);
        if (boss.isPresent() && items.stream().anyMatch(item -> boss.get().findUnique(item.getId()).isPresent()))
        {
            DropContext context = new DropContext(source, client.getTickCount(), metadata);
            correlator.addDrop(boss.get(), items, context);
            removePendingItems(items);
            return;
        }
        for (ItemStack item : items)
        {
            List<ActivityDefinition> candidates = fullCatalog.resolve(source, item.getId());
            if (candidates.size() == 1)
            {
                queueGenericDrop(candidates.get(0), item.getId(), metadata);
            }
            else if (candidates.size() > 1)
            {
                addPendingAttribution(item.getId(), candidates);
            }
        }
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Double> extractRateMetadata(Object metadata)
    {
        if (!(metadata instanceof Map))
        {
            return Collections.emptyMap();
        }
        Map<String, Double> result = new HashMap<>();
        ((Map<?, ?>) metadata).forEach((key, value) -> {
            if (key instanceof String && value instanceof Number)
            {
                result.put((String) key, ((Number) value).doubleValue());
            }
        });
        return result;
    }

    private void announce(TrackedUnique record)
    {
        latestShareRecord = record;
        clientThread.invokeLater(() -> announceOnClientThread(record));
    }

    private void announceOnClientThread(TrackedUnique record)
    {
        if (config.celebrationSound())
        {
            SpoonSound sound = configuredSound(record.getTier());
            if (sound.isAudible())
            {
                client.playSoundEffect(sound.getSoundEffectId(), config.soundVolume().getVolume());
            }
        }
        if (config.chatMessage())
        {
            String tier = record.getTier() == null ? "an ungraded Mystery Spoon" : "a " + record.getTier().getDisplayName();
            String kc = record.getObtainedKillCount() == null
                ? "unknown completion count" : "count " + record.getObtainedKillCount();
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Spoon Tracker: " + record.getItemName() + " earned " + tier + " at " + kc + "!", null);
        }
    }

    private SpoonSound configuredSound(SpoonTier tier)
    {
        if (tier == null)
        {
            return config.ungradedSound();
        }

        switch (tier)
        {
            case DIAMOND:
                return config.diamondSound();
            case GOLD:
                return config.goldSound();
            case SILVER:
                return config.silverSound();
            case WOODEN:
                return config.woodenSound();
            case BENT:
                return config.bentSound();
            case SPORK:
                return config.sporkSound();
            default:
                return config.ungradedSound();
        }
    }

    private void loadProfile()
    {
        records = store.load();
        pendingAttributions = pendingStore.load();
        latestShareRecord = records.stream()
            .max(java.util.Comparator.comparing(TrackedUnique::getObtainedAt,
                java.util.Comparator.nullsFirst(java.util.Comparator.naturalOrder())))
            .orElse(null);
        refreshPanel();
    }

    private void preloadHiscoreKillCounts()
    {
        if (client.getLocalPlayer() == null || correlator == null)
        {
            return;
        }
        String username = Text.removeTags(client.getLocalPlayer().getName());
        HiscoreEndpoint endpoint = HiscoreEndpoint.fromWorldTypes(client.getWorldType());
        hiscoreClient.lookupAsync(username, endpoint).whenComplete((result, error) -> {
            if (error != null)
            {
                LOG.debug("Unable to preload Spoon Tracker boss KC for {}", username, error);
                return;
            }
            clientThread.invokeLater(() -> acceptHiscoreKillCounts(username, result));
        });
    }

    private void acceptHiscoreKillCounts(String username, HiscoreResult result)
    {
        if (result == null || client.getLocalPlayer() == null
            || !Text.removeTags(client.getLocalPlayer().getName()).equalsIgnoreCase(username))
        {
            return;
        }
        int loaded = 0;
        for (HiscoreSkill hiscoreSkill : HiscoreSkill.values())
        {
            Skill value = result.getSkill(hiscoreSkill);
            if (value != null && value.getLevel() >= 0
                && correlator.preloadKnownCount(hiscoreSkill.getName(), value.getLevel()))
            {
                loaded++;
            }
        }
        LOG.debug("Preloaded {} Spoon Tracker boss kill counts from hiscores", loaded);
    }

    private void refreshPanel()
    {
        List<TrackedUnique> snapshot = new ArrayList<>(records);
        List<HistoricalLuckResult> luckSnapshot = new ArrayList<>(historicalResults);
        String statusSnapshot = historicalStatus;
        int pendingCount = pendingAttributions.size();
        SwingUtilities.invokeLater(() -> panel.refresh(snapshot, luckSnapshot, statusSnapshot, pendingCount));
    }

    private void resetRecords()
    {
        store.reset();
        records = new ArrayList<>();
        correlator.clear();
        celebrations.clear();
        latestShareRecord = null;
        refreshPanel();
    }

    private void copyLatestShareCard()
    {
        BufferedImage card = renderLatestShareCard();
        if (card == null)
        {
            shareStatus("No spoon is available to share yet.");
            return;
        }
        try
        {
            Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransferable(card), null);
            shareStatus("Latest spoon card copied. Paste it straight into Discord!");
        }
        catch (RuntimeException ex)
        {
            LOG.warn("Unable to copy Spoon Tracker share card", ex);
            shareStatus("Could not access the clipboard; try Save latest share card instead.");
        }
    }

    private void saveLatestShareCard()
    {
        TrackedUnique shareRecord = getShareRecord();
        BufferedImage card = renderLatestShareCard();
        if (card == null || shareRecord == null)
        {
            shareStatus("No spoon is available to share yet.");
            return;
        }
        File directory = new File(RuneLite.SCREENSHOT_DIR, "Spoon Tracker");
        String item = shareRecord.getItemName().replaceAll("[^A-Za-z0-9]+", "-")
            .replaceAll("(^-|-$)", "").toLowerCase();
        File destination = new File(directory, "spoon-" + item + "-" + System.currentTimeMillis() + ".png");
        try
        {
            Files.createDirectories(directory.toPath());
            ImageIO.write(card, "png", destination);
            shareStatus("Spoon card saved to RuneLite screenshots/Spoon Tracker.");
        }
        catch (IOException ex)
        {
            LOG.warn("Unable to save Spoon Tracker share card to {}", destination, ex);
            shareStatus("Could not save the spoon card; check the RuneLite log for details.");
        }
    }

    private BufferedImage renderLatestShareCard()
    {
        TrackedUnique shareRecord = getShareRecord();
        if (shareRecord == null)
        {
            return null;
        }
        return shareCardRenderer.render(shareRecord,
            itemManager.getImage(shareRecord.getDisplayItemId()));
    }

    private TrackedUnique getShareRecord()
    {
        if (latestShareRecord != null)
        {
            return latestShareRecord;
        }
        return null;
    }

    private void shareStatus(String message)
    {
        clientThread.invokeLater(() -> client.addChatMessage(
            ChatMessageType.GAMEMESSAGE, "", "Spoon Tracker: " + message, null));
    }

    private List<TrackedUnique> collectionLogRecords()
    {
        return new ArrayList<>(records);
    }

    private List<HistoricalLuckResult> historicalLuckResults()
    {
        return new ArrayList<>(historicalResults);
    }

    private void refreshHistoricalLuck()
    {
        if (!config.historicalLuck())
        {
            historicalStatus = "Enable Historical Log Luck in settings";
            refreshPanel();
            return;
        }
        captureOpenCollectionLogPage();
        recalculateHistoricalLuck();
    }

    private void manualRefreshHistoricalLuck()
    {
        refreshHistoricalLuck();
    }

    private void captureOpenCollectionLogPage()
    {
        collectionLogCapture.capture(client).ifPresent(snapshot -> {
            snapshot.getCounters().forEach((source, count) -> correlator.preloadKnownCount(source, count));
            if (config.historicalLuck())
            {
                acceptHistoricalSnapshot(snapshot);
            }
        });
    }

    private void acceptHistoricalSnapshot(HistoricalLogSnapshot snapshot)
    {
        if (snapshot.getSource().startsWith("In-game Collection Log: "))
        {
            fullCatalog.observePage(snapshot.getSource().substring("In-game Collection Log: ".length()),
                snapshot.getQuantities().keySet());
        }
        Map<Integer, Integer> oldItems = historicalSnapshot == null
            ? Collections.emptyMap() : historicalSnapshot.getQuantities();
        Map<String, Integer> oldCounters = historicalSnapshot == null
            ? Collections.emptyMap() : historicalSnapshot.getCounters();
        historicalSnapshot = historicalSnapshot == null ? snapshot : historicalSnapshot.merge(snapshot);
        if (!historicalSnapshot.getQuantities().equals(oldItems)
            || !historicalSnapshot.getCounters().equals(oldCounters))
        {
            recalculateHistoricalLuck();
        }
    }

    private void recalculateHistoricalLuck()
    {
        if (historicalSnapshot == null)
        {
            historicalResults = new ArrayList<>();
            historicalStatus = "Open Collection Log pages to build your local Log Luck snapshot";
        }
        else
        {
            historicalResults = historicalLuckCalculator.calculate(historicalSnapshot, historicalAssumptions);
            historicalStatus = historicalSnapshot.getSource() + " • "
                + historicalResults.size() + " obtained items • session preview";
        }
        refreshPanel();
    }

    private void clearHistoricalSession()
    {
        historicalSnapshot = null;
        historicalResults = new ArrayList<>();
        historicalStatus = config != null && config.historicalLuck()
            ? "Historical session cleared; open a Collection Log page"
            : "Enable Historical Log Luck to begin";
        if (panel != null)
        {
            refreshPanel();
        }
    }

    private void handleCollectionLogNotification()
    {
        Widget title = client.getWidget(InterfaceID.NotificationDisplay.TITLE_TEXT);
        Widget main = client.getWidget(InterfaceID.NotificationDisplay.MAIN);
        String titleText = title == null ? "" : Text.removeTags(title.getText()).toLowerCase();
        String mainText = main == null ? "" : Text.removeTags(main.getText()).toLowerCase();
        if (!titleText.contains("collection") && !mainText.contains("collection log"))
        {
            return;
        }
        int itemId = findWidgetItemId(main);
        if (itemId <= 0 || fullCatalog.findItem(itemId).isEmpty())
        {
            return;
        }
        String identity = itemId + ":" + client.getTickCount();
        if (identity.equals(lastNotificationIdentity))
        {
            return;
        }
        lastNotificationIdentity = identity;

        for (BossDefinition boss : catalog.getBosses())
        {
            if (boss.findUnique(itemId).isPresent())
            {
                return; // Existing encounter adapters retain their KC-aware path.
            }
        }
        List<ActivityDefinition> candidates = fullCatalog.activitiesForItem(itemId);
        candidates.removeIf(candidate -> records.stream().anyMatch(record ->
            record.getActivityKey().equals(candidate.getKey()) && record.getCanonicalItemId() == itemId));
        if (candidates.size() == 1)
        {
            queueGenericDrop(candidates.get(0), itemId, Collections.emptyMap());
        }
        else if (candidates.size() > 1)
        {
            addPendingAttribution(itemId, candidates);
        }
    }

    private static int findWidgetItemId(Widget widget)
    {
        if (widget == null) return -1;
        if (widget.getItemId() > 0) return widget.getItemId();
        Widget[] children = widget.getChildren();
        if (children != null)
        {
            for (Widget child : children)
            {
                int id = findWidgetItemId(child);
                if (id > 0) return id;
            }
        }
        return -1;
    }

    private void queueGenericDrop(ActivityDefinition activity, int itemId, Map<String, Double> metadata)
    {
        activityCorrelator.add(activity, itemId,
            new DropContext(activity.getName(), client.getTickCount(), metadata));
    }

    private void finalizeGenericDrop(ActivityDefinition activity, int itemId, Integer completionCount,
        DropContext context)
    {
        List<TrackedUnique> additions = trackingEngine.recognizeActivity(activity,
            Collections.singletonList(new ItemStack(itemId, 1)), completionCount, context, records);
        for (TrackedUnique addition : additions)
        {
            records.add(addition);
            if (config.celebrationOverlay()) celebrations.enqueue(addition);
            announce(addition);
        }
        if (!additions.isEmpty())
        {
            store.save(records);
            pendingAttributions.removeIf(pending -> pending.getItemId() == itemId);
            pendingStore.save(pendingAttributions);
            refreshPanel();
        }
    }

    private void addPendingAttribution(int itemId, List<ActivityDefinition> candidates)
    {
        if (pendingAttributions.stream().anyMatch(pending -> pending.getItemId() == itemId)) return;
        String name = fullCatalog.findItem(itemId).map(FullCollectionLogCatalog.CatalogItem::getName)
            .orElse("Item " + itemId);
        pendingAttributions.add(new PendingAttribution(itemId, name, Clock.systemUTC().instant(), candidates));
        pendingStore.save(pendingAttributions);
        refreshPanel();
    }

    private void removePendingItems(Collection<ItemStack> items)
    {
        boolean changed = pendingAttributions.removeIf(pending -> items.stream()
            .anyMatch(item -> item.getId() == pending.getItemId()));
        if (changed) pendingStore.save(pendingAttributions);
    }

    private void resolvePendingAttribution()
    {
        if (pendingAttributions.isEmpty())
        {
            shareStatus("No drops are waiting for activity attribution.");
            return;
        }
        PendingAttribution pending = pendingAttributions.get(0);
        List<String> choices = new ArrayList<>(pending.getActivityNames());
        choices.add("Dismiss without spoon");
        Object selection = JOptionPane.showInputDialog(panel,
            "Where did you receive " + pending.getItemName() + "?",
            "Resolve Spoon Activity", JOptionPane.QUESTION_MESSAGE, null,
            choices.toArray(), choices.get(0));
        if (selection == null) return;
        if ("Dismiss without spoon".equals(selection.toString()))
        {
            pendingAttributions.remove(0);
            pendingStore.save(pendingAttributions);
            refreshPanel();
            return;
        }
        int index = pending.getActivityNames().indexOf(selection.toString());
        if (index < 0) return;
        String key = pending.getActivityKeys().get(index);
        for (ActivityDefinition candidate : fullCatalog.activitiesForItem(pending.getItemId()))
        {
            if (candidate.getKey().equals(key))
            {
                pendingAttributions.remove(0);
                pendingStore.save(pendingAttributions);
                finalizeGenericDrop(candidate, pending.getItemId(), null,
                    new DropContext(candidate.getName(), client.getTickCount(), Collections.emptyMap()));
                return;
            }
        }
    }

    private void clearPendingAttributions()
    {
        pendingStore.reset();
        pendingAttributions = new ArrayList<>();
        refreshPanel();
    }
}

package com.spoontracker;

import java.awt.Color;
import java.util.Optional;
import net.runelite.api.SoundEffectID;

public enum SpoonTier
{
    DIAMOND("Diamond Spoon", new Color(102, 239, 255), "spoon-diamond.png", SoundEffectID.PRAYER_DEPLETE_TWINKLE),
    GOLD("Golden Spoon", new Color(255, 194, 51), "spoon-gold.png", SoundEffectID.GE_COIN_TINKLE),
    SILVER("Silver Spoon", new Color(205, 215, 225), "spoon-silver.png", SoundEffectID.GE_ADD_OFFER_DINGALING),
    WOODEN("Wooden Spoon", new Color(174, 112, 59), "spoon-wooden.png", SoundEffectID.TREE_CHOP),
    BENT("Bent Spoon", new Color(157, 144, 135), "spoon-bent.png", SoundEffectID.SMITH_ANVIL_TONK),
    SPORK("Spork", new Color(224, 92, 92), "spoon-spork.png", SoundEffectID.MAGIC_SPLASH_BOING);

    private final String displayName;
    private final Color color;
    private final String iconResource;
    private final int soundEffectId;

    SpoonTier(String displayName, Color color, String iconResource, int soundEffectId)
    {
        this.displayName = displayName;
        this.color = color;
        this.iconResource = iconResource;
        this.soundEffectId = soundEffectId;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public Color getColor()
    {
        return color;
    }

    public String getIconResource()
    {
        return iconResource;
    }

    public int getSoundEffectId()
    {
        return soundEffectId;
    }

    public static Optional<SpoonTier> from(int killCount, double expectedKillCount)
    {
        if (killCount < 1 || !Double.isFinite(expectedKillCount) || expectedKillCount <= 0)
        {
            return Optional.empty();
        }

        double ratio = killCount / expectedKillCount;
        if (ratio <= .10)
        {
            return Optional.of(DIAMOND);
        }
        if (ratio <= .50)
        {
            return Optional.of(GOLD);
        }
        if (ratio <= 1.0)
        {
            return Optional.of(SILVER);
        }
        if (ratio <= 2.0)
        {
            return Optional.of(WOODEN);
        }
        if (ratio <= 5.0)
        {
            return Optional.of(BENT);
        }
        return Optional.of(SPORK);
    }
}

package com.spoontracker;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.game.ItemStack;

final class ActivityCountCorrelator
{
    private static final int WINDOW_TICKS = 10;
    private static final Pattern[] PATTERNS = {
        Pattern.compile("Your (?:(?:completion count for|subdued|completed)\\s+)?(.+?)\\s+"
            + "(?:(?:(?:kill|harvest|lap|completion|success|total ticket)\\s+)?(?:count\\s+)?)?"
            + "is:\\s*([\\d,]+)\\.?", Pattern.CASE_INSENSITIVE),
        Pattern.compile("Your (.+?) count is: ([\\d,]+)\\.?", Pattern.CASE_INSENSITIVE),
        Pattern.compile("Your kill count for (.+?) is: ([\\d,]+)\\.?", Pattern.CASE_INSENSITIVE)
    };
    private final Deque<Pending> pending = new ArrayDeque<>();
    private final Map<String, SeenCount> recent = new HashMap<>();

    void add(ActivityDefinition activity, int itemId, DropContext context)
    {
        for (Pending existing : pending)
        {
            if (existing.activity.getKey().equals(activity.getKey()) && existing.itemId == itemId
                && Math.abs(existing.context.getTick() - context.getTick()) <= WINDOW_TICKS)
            {
                return;
            }
        }
        SeenCount seen = recent.get(activity.getKey());
        Integer count = seen != null && Math.abs(context.getTick() - seen.tick) <= WINDOW_TICKS
            ? seen.count : null;
        pending.add(new Pending(activity, itemId, context, count));
    }

    void parse(String message, int tick)
    {
        String clean = message == null ? "" : message.replaceAll("<[^>]+>", "");
        for (Pattern pattern : PATTERNS)
        {
            Matcher matcher = pattern.matcher(clean);
            if (!matcher.find()) continue;
            String source = BossDefinition.normalize(matcher.group(1));
            int count;
            try { count = Integer.parseInt(matcher.group(2).replace(",", "")); }
            catch (NumberFormatException ex) { return; }
            for (Pending drop : pending)
            {
                String activity = BossDefinition.normalize(drop.activity.getName());
                if ((activity.contains(source) || source.contains(activity))
                    && Math.abs(drop.context.getTick() - tick) <= WINDOW_TICKS)
                {
                    drop.count = count;
                    recent.put(drop.activity.getKey(), new SeenCount(count, tick));
                }
            }
            return;
        }
    }

    List<Pending> drainReady(int tick)
    {
        List<Pending> ready = new ArrayList<>();
        while (!pending.isEmpty())
        {
            Pending first = pending.peek();
            if (first.count == null && tick - first.context.getTick() <= WINDOW_TICKS) break;
            ready.add(pending.remove());
        }
        recent.values().removeIf(value -> tick - value.tick > WINDOW_TICKS);
        return ready;
    }

    void clear()
    {
        pending.clear();
        recent.clear();
    }

    static final class Pending
    {
        private final ActivityDefinition activity;
        private final int itemId;
        private final DropContext context;
        private Integer count;

        Pending(ActivityDefinition activity, int itemId, DropContext context, Integer count)
        {
            this.activity = activity;
            this.itemId = itemId;
            this.context = context;
            this.count = count;
        }

        ActivityDefinition getActivity() { return activity; }
        int getItemId() { return itemId; }
        DropContext getContext() { return context; }
        Integer getCount() { return count; }
    }

    private static final class SeenCount
    {
        private final int count;
        private final int tick;
        private SeenCount(int count, int tick) { this.count = count; this.tick = tick; }
    }
}

