import com.peanubnutter.collectionlogluck.luck.LogItemSourceInfo;
import java.time.Clock;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

public final class CollectionLogCaptureService
{
    private static final Pattern COUNTER = Pattern.compile("^(.+?):\\s*([\\d,]+)$");
    private final Clock clock;

    public CollectionLogCaptureService(Clock clock)
    {
        this.clock = clock;
    }

    public Optional<HistoricalLogSnapshot> capture(Client client)
    {
        Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
        Widget itemsRoot = client.getWidget(InterfaceID.Collection.ITEMS);
        if (header == null || header.isHidden() || itemsRoot == null)
        {
            return Optional.empty();
        }
        Map<Integer, Integer> quantities = new LinkedHashMap<>();
        collectItems(itemsRoot, quantities);
        if (quantities.isEmpty())
        {
            return Optional.empty();
        }
        Map<String, Integer> counters = new LinkedHashMap<>();
        Widget main = client.getWidget(InterfaceID.Collection.MAIN);
        if (main != null)
        {
            collectCounters(main, counters);
        }
        String username = client.getLocalPlayer() == null
            ? "Unknown" : Text.removeTags(client.getLocalPlayer().getName());
        String page = Text.removeTags(header.getText());
        return Optional.of(new HistoricalLogSnapshot(username, clock.instant(),
            "In-game Collection Log: " + page, quantities, counters));
    }

    private static void collectItems(Widget widget, Map<Integer, Integer> quantities)
    {
        if (widget.getItemId() > 0)
        {
            quantities.merge(widget.getItemId(), Math.max(0, widget.getItemQuantity()), Math::max);
        }
        Widget[] children = widget.getChildren();
        if (children != null)
        {
            for (Widget child : children)
            {
                if (child != null) collectItems(child, quantities);
            }
        }
    }

    private static void collectCounters(Widget widget, Map<String, Integer> counters)
    {
        String text = Text.removeTags(widget.getText());
        Matcher matcher = COUNTER.matcher(text == null ? "" : text.trim());
        if (matcher.matches() && LogItemSourceInfo.findByName(matcher.group(1)) != null)
        {
            try
            {
                counters.merge(matcher.group(1),
                    Integer.parseInt(matcher.group(2).replace(",", "")), Math::max);
            }
            catch (NumberFormatException ignored)
            {
                // Ignore malformed widget text.
            }
        }
        Widget[] children = widget.getChildren();
        if (children != null)
        {
            for (Widget child : children)
            {
                if (child != null) collectCounters(child, counters);
            }
        }
    }
}

