import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class SpoonTrackerStore
{
    static final String GROUP = "spoontracker";
    static final String RECORDS_KEY = "records_v1";
    private static final Logger LOG = LoggerFactory.getLogger(SpoonTrackerStore.class);

    private final ConfigManager configManager;
    private final Gson gson;

    public SpoonTrackerStore(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    public List<TrackedUnique> load()
    {
        String json = configManager.getRSProfileConfiguration(GROUP, RECORDS_KEY);
        if (json == null || json.trim().isEmpty())
        {
            return new ArrayList<>();
        }
        try
        {
            TrackedUnique[] storedRecords = gson.fromJson(json, TrackedUnique[].class);
            if (storedRecords == null)
            {
                return new ArrayList<>();
            }
            List<TrackedUnique> records = new ArrayList<>(Arrays.asList(storedRecords));
            records.removeIf(record -> record == null || (record.getSchemaVersion() != 1
                    && record.getSchemaVersion() != 2)
                || record.getBossKey() == null || record.getCanonicalItemId() <= 0);
            boolean migrated = false;
            List<TrackedUnique> normalized = new ArrayList<>();
            for (TrackedUnique record : records)
            {
                if (record.getSchemaVersion() == 1)
                {
                    normalized.add(new TrackedUnique(record.getBossKey(), record.getBossName(),
                        record.getCanonicalItemId(), record.getDisplayItemId(), record.getItemName(),
                        record.getObtainedKillCount(), record.getEffectiveDenominator(), record.getTier(),
                        record.getObtainedAt(), record.getCatalogVersion(), "Legacy captured rate",
                        record.getEffectiveDenominator() == null
                            ? RateConfidence.UNAVAILABLE : RateConfidence.EXACT,
                        record.getEffectiveDenominator() == null ? "Legacy record was ungraded" : null));
                    migrated = true;
                }
                else
                {
                    normalized.add(record);
                }
            }
            if (migrated)
            {
                save(normalized);
            }
            return normalized;
        }
        catch (JsonParseException | IllegalStateException ex)
        {
            LOG.warn("Unable to read Spoon Tracker records; leaving the malformed value untouched", ex);
            return new ArrayList<>();
        }
    }

    public void save(List<TrackedUnique> records)
    {
        configManager.setRSProfileConfiguration(GROUP, RECORDS_KEY,
            gson.toJson(records == null ? Collections.emptyList() : records));
    }

    public void reset()
    {
        configManager.unsetRSProfileConfiguration(GROUP, RECORDS_KEY);
    }
}

