package com.spoontracker;

import com.google.common.collect.ImmutableMap;
import com.peanubnutter.collectionlogluck.CollectionLogLuckConfig;
import com.peanubnutter.collectionlogluck.luck.LogItemInfo;
import com.peanubnutter.collectionlogluck.luck.drop.AbstractDrop;
import com.peanubnutter.collectionlogluck.luck.drop.DropLuck;
import com.peanubnutter.collectionlogluck.model.CollectionLog;
import com.peanubnutter.collectionlogluck.model.CollectionLogItem;
import com.peanubnutter.collectionlogluck.model.CollectionLogKillCount;
import com.peanubnutter.collectionlogluck.model.CollectionLogPage;
import com.peanubnutter.collectionlogluck.model.CollectionLogTab;
import com.peanubnutter.collectionlogluck.util.LuckUtils;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public final class HistoricalLuckCalculator
{
    public List<HistoricalLuckResult> calculate(HistoricalLogSnapshot snapshot,
        CollectionLogLuckConfig config)
    {
        List<CollectionLogItem> items = new ArrayList<>();
        snapshot.getQuantities().forEach((id, quantity) -> {
            LogItemInfo info = LogItemInfo.findByItemId(id);
            if (info != null)
            {
                items.add(new CollectionLogItem(id, info.getItemName(), quantity, quantity > 0, items.size()));
            }
        });
        List<CollectionLogKillCount> counts = new ArrayList<>();
        snapshot.getCounters().forEach((name, count) ->
            counts.add(new CollectionLogKillCount(name, count, counts.size())));
        CollectionLogPage page = new CollectionLogPage("Captured Collection Log", items, counts, true);
        CollectionLogTab tab = new CollectionLogTab("Captured", ImmutableMap.of(page.getName(), page));
        CollectionLog log = new CollectionLog(snapshot.getUsername(), 0, items.size(), 0, items.size(),
            ImmutableMap.of(tab.getName(), tab));

        List<HistoricalLuckResult> results = new ArrayList<>();
        for (CollectionLogItem item : items)
        {
            if (item.getQuantity() <= 0)
            {
                continue;
            }
            LogItemInfo info = LogItemInfo.findByItemId(item.getId());
            DropLuck drop = info.getDropProbabilityDistribution();
            String mechanic = drop.getClass().getSimpleName();
            String reason = drop.getIncalculableReason(item, config);
            if (reason != null)
            {
                results.add(unavailable(item, mechanic, reason));
                continue;
            }
            double luck = drop.calculateLuck(item, log, config);
            double dryness = drop.calculateDryness(item, log, config);
            if (!valid(luck) || !valid(dryness))
            {
                results.add(unavailable(item, mechanic,
                    "Required activity counter or mechanic is unavailable"));
                continue;
            }
            double overall = LuckUtils.getOverallLuck(luck, dryness);
            boolean estimated = drop instanceof AbstractDrop
                && !((AbstractDrop) drop).getConfigOptions().isEmpty();
            Double expected = drop instanceof AbstractDrop
                ? ((AbstractDrop) drop).getExpectedSuccesses(log, config) : null;
            results.add(new HistoricalLuckResult(item.getId(), item.getName(), item.getQuantity(),
                expected, luck, dryness, overall, HistoricalLuckResult.previewTier(overall),
                mechanic, estimated ? RateConfidence.ESTIMATED : RateConfidence.EXACT,
                drop.getKillCountDescription(log)));
        }
        results.sort(Comparator.comparing(HistoricalLuckResult::getOverallLuck,
            Comparator.nullsLast(Comparator.reverseOrder())));
        return results;
    }

    private static HistoricalLuckResult unavailable(CollectionLogItem item, String mechanic, String reason)
    {
        return new HistoricalLuckResult(item.getId(), item.getName(), item.getQuantity(),
            null, null, null, null, null, mechanic, RateConfidence.UNAVAILABLE, reason);
    }

    private static boolean valid(double value)
    {
        return Double.isFinite(value) && value >= 0 && value <= 1;
    }
}

