	{
		for (CollectionLogItem item : getItems())
		{
			if (item.getId() == itemId)
			{
				return item;
			}
		}
		return null;
	}

	public CollectionLogKillCount getKillCountByName(String name)
	{
		for (CollectionLogKillCount killCount : getKillCounts())
		{
			if (killCount.getName().equals(name))
			{
				return killCount;
			}
		}
		return null;
	}
